const Q33=[{n:1,q:"El Reglamento General de Conductores, aprobado por medio del Real Decreto 818/2009, de 8 de mayo",o:{a:"Consta de seis Títulos.",b:"Tiene nueve anexos.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: el RGCond tiene 6 Títulos y 9 Anexos.",d:"✓ Respuesta oficial. Las dos son ciertas."}},
{n:2,q:"El Reglamento General de Conductores (RD 818/2009), consta de:",o:{a:"Ocho anexos.",b:"Seis Disposiciones finales y una derogatoria.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Tiene nueve anexos, no ocho.",b:"Tiene cuatro disposiciones finales y una derogatoria, no seis.",c:"✓ Respuesta oficial. Las dos son falsas.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: ambas afirmaciones son incorrectas."}},
{n:3,q:"El Reglamento General de Conductores (RD 818/2009), consta de:",o:{a:"Cinco Títulos.",b:"Once Disposiciones Adicionales y doce Transitorias.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Tiene seis Títulos, no cinco.",b:"El número de disposiciones adicionales y transitorias no coincide.",c:"✓ Respuesta oficial. Las dos son falsas.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: ambas son incorrectas."}},
{n:4,q:"El Título I del Reglamento General de Conductores (RD 818/2009), se denomina:",o:{a:"Del permiso y de la licencia de conducción.",b:"De los permisos de conducción expedidos por otros países.",c:"De la enseñanza en la conducción y de las pruebas de aptitud a realizar para obtener autorizaciones administrativas para conducir.",d:"De las autorizaciones administrativas para conducir."},correct:"d",why:{a:"Es el Cap.I del Título I.",b:"Es el Cap.II del Título I.",c:"Es el Título II.",d:"Correcto: Título I — De las autorizaciones administrativas para conducir."}},
{n:5,q:"El Capítulo IV del Título I del Reglamento General de Conductores (RD 818/2009)...",o:{a:"Se denomina \"De la nulidad o lesividad y pérdida de vigencia de las autorizaciones administrativas para conducir\"",b:"Consta de dos secciones.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"✓ Respuesta oficial. Parcial.",b:"Parcial.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: denominación y estructura.",d:"Ambas son ciertas."}},
{n:6,q:"Con respecto a los enunciados de los cuatro Capítulos que contiene el Título I del Reglamento General de Conductores (RD 818/2009), indique cual de los siguientes no es correcto:",o:{a:"Capítulo I: Del permiso y de la licencia de conducción.",b:"Capítulo II: De los permisos de conducción expedidos por otros países.",c:"Capítulo III: Otras autorizaciones administrativas para conducir.",d:"Capítulo IV: De la validez y equivalencias de las autorizaciones administrativas para conducir."},correct:"d",why:{a:"Correcto.",b:"Correcto.",c:"Correcto.",d:"El Cap.IV es «De la nulidad o lesividad y pérdida de vigencia», no «De la validez y equivalencias»."}},
{n:7,q:"El Capitulo II del Título I del Reglamento General de Conductores (RD 818/2009):",o:{a:"Abarca los artículos 11 a 23.",b:"Tiene tres secciones.",c:"Se denomina \" Del permiso y de la licencia de conducción\".",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{a:"Cierto.",b:"✓ Respuesta oficial. Cierto.",c:"Cierto.",d:"⚠ Mi respuesta inicial (incorrecta): Las tres son correctas."}},
{n:8,q:"El Capitulo III del Título I del Reglamento General de Conductores (RD 818/2009):",o:{a:"Abarca los artículos 11 a 23.",b:"Tiene dos secciones.",c:"Se denomina \"De los permisos de conducción expedidos por otros países\".",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{a:"Esos artículos son del Cap.II.",b:"✓ Respuesta oficial. La estructura no coincide.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: denominación del Cap.III.",d:"Solo la c es cierta."}},
{n:9,q:"El Título II del Reglamento General de Conductores (RD 818/2009), se denomina:",o:{a:"Del permiso y de la licencia de conducción.",b:"De los permisos de conducción expedidos por otros países.",c:"De las autorizaciones administrativas para conducir.",d:"De la enseñanza de la conducción y de las pruebas de aptitud a realizar para obtener autorizaciones administrativas para conducir."},correct:"d",why:{a:"Es Cap.I del Tit.I.",b:"Es Cap.III del Tit.I.",c:"Es el Tit.I.",d:"Correcto: Título II."}},
{n:10,q:"Con respecto a los enunciados de los cuatro Capítulos que abarca el Título II del Reglamento General de Conductores (RD 818/2009), indique cual de los siguientes no es correcto:",o:{a:"Cap. I: Disposiciones generales.",b:"Cap. II: De las pruebas de aptitud psicofísica.",c:"Cap. III: De las autorizaciones administrativas para conducir.",d:"Cap. IV: De las pruebas a realizar para comprobar los conocimientos para obtener o prorrogar la autorización especial que habilita para conducir vehículos que transporten mercancías peligrosas."},correct:"c",why:{a:"Correcto.",b:"Correcto.",c:"El Cap.III es «De las pruebas a realizar para comprobar los conocimientos, aptitudes y comportamientos…», no «De las autorizaciones administrativas para conducir».",d:"Correcto."}},
{n:11,q:"El Capítulo III del Título II del Reglamento General de Conductores (RD 818/2009)...",o:{a:"Consta de dos secciones.",b:"Se denomina \"De las pruebas a realizar para comprobar los conocimientos, aptitudes y comportamientos necesarios para conducir vehículos de motor y ciclomotores.",c:"Abarca los artículos 47 a 62.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres son correctas."}},
{n:12,q:"El Capítulo II del Título II del Reglamento General de Conductores (RD 818/2009), se denomina:",o:{a:"De las pruebas de aptitud psicofísica.",b:"De la enseñanza de la conducción y de las pruebas de aptitud a realizar para obtener autorizaciones administrativas para conducir.",c:"Del permiso comunitario de conducción.",d:"Vehículos a utilizar en las pruebas de control de aptitudes y comportamientos."},correct:"a",why:{a:"Correcto: Cap.II del Tit.II.",b:"Es el propio Título II.",c:"No es el Cap.II.",d:"No es el Cap.II."}},
{n:13,q:"El Título III del Reglamento General de Conductores (RD 818/2009), se denomina:",o:{a:"Otras autorizaciones administrativas para conducir.",b:"De los permisos de conducción expedidos por las Escuelas y Organismos militares y de la Dirección General de la Policía y de la Guardia Civil.",c:"De las infracciones y Sanciones.",d:"De las pruebas a realizar para comprobar los conocimientos para obtener o prorrogar la autorización especial que habilita para conducir vehículos que transporten mercancías peligrosas."},correct:"b",why:{a:"No es ese Título.",b:"✓ Respuesta oficial. No es ese Título.",c:"Es Título IV.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: Título III."}},
{n:14,q:"El Título IV del Reglamento General de Conductores (RD 818/2009), se denomina:",o:{a:"De las infracciones y sanciones.",b:"Del Registro de Conductores e Infractores.",c:"Permiso de conducción de la Unión Europea.",d:"Licencia de conducción y otras autorizaciones para conducir."},correct:"a",why:{a:"Correcto: Título IV.",b:"Es Título V.",c:"No es Título.",d:"No es Título."}},
{n:15,q:"El Título V del Reglamento General de Conductores (RD 818/2009), se denomina:",o:{a:"De las infracciones y sanciones.",b:"Del Registro de Conductores e Infractores.",c:"Permiso de conducción de la Unión Europea.",d:"Licencia de conducción y otras autorizaciones para conducir."},correct:"b",why:{a:"Es Título IV.",b:"Correcto: Título V.",c:"No es Título.",d:"No es Título."}},
{n:16,q:"Con respecto a los enunciados de los nueve Anexos que contiene el Reglamento General de Conductores (RD 818/2009), indique cual de los siguientes no es correcto:",o:{a:"Anexo I: Convalidación de los permisos de conducción.",b:"Anexo II: Licencia de conducción y otras autorizaciones para conducir.",c:"Anexo III: Documentación para obtener las distintas autorizaciones para conducir.",d:"Anexo IV: Aptitudes psicofísicas para obtener o prorrogar el permiso o la licencia de conducción."},correct:"a",why:{a:"El Anexo I es «Permiso de conducción de la Unión Europea», no «Convalidación de permisos».",b:"Correcto.",c:"Correcto.",d:"Correcto."}},
{n:17,q:"Con respecto a los enunciados de los nueve Anexos que contiene el Reglamento General de Conductores (RD 818/2009), indique cual de los siguientes no es correcto:",o:{a:"Anexo V: Pruebas a realizar por los solicitantes de las distintas autorizaciones.",b:"Anexo VI: Organización, desarrollo y criterios de calificación de las pruebas de control de conocimientos y de control de aptitudes y comportamientos.",c:"Anexo VII: Vehículos a utilizar en las pruebas de control de aptitudes y comportamientos.",d:"Anexo VIII: Permisos de conducción de la Unión Europea."},correct:"d",why:{a:"Correcto.",b:"Correcto.",c:"Correcto.",d:"El Anexo VIII es «Personal examinador…», no «Permisos UE» (eso es Anexo I)."}},
{n:18,q:"Con respecto a los enunciados de los nueve Anexos que contiene el Reglamento General de Conductores (RD 818/2009), indique cual de los siguientes no es correcto:",o:{a:"Anexo I: Permiso de conducción de la Unión Europea.",b:"Anexo II: Convalidación de los permisos de conducción.",c:"Anexo VIII: Personal examinador encargado de calificar las pruebas de control de aptitudes y comportamientos.",d:"Anexo IX: Procedimiento para la organización y regulación de las pruebas de control de aptitudes y comportamientos en las pruebas de circulación en vías abiertas al tráfico en general por las Jefaturas Provinciales de Tráfico"},correct:"b",why:{a:"Correcto.",b:"El Anexo II es «Licencia de conducción y otras autorizaciones», no «Convalidación».",c:"Correcto.",d:"Correcto."}},
{n:19,q:"En el Reglamento General de Conductores (RD 818/2009), la expresión \"Del Registro de Conductores e Infractores\" es la denominación de :",o:{a:"Su Título II",b:"Su Título V.",c:"El capítulo II de su Título I.",d:"Su Anexo V."},correct:"b",why:{a:"Tit.II es enseñanza/pruebas.",b:"Correcto: Título V.",c:"No es Cap.II.",d:"No es Anexo V."}},
{n:20,q:"El Anexo III del Reglamento General de Conductores (RD 818/2009), se denomina:",o:{a:"De las infracciones y sanciones.",b:"Del Registro de conductores e infractores.",c:"Documentación para obtener las distintas autorizaciones para conducir.",d:"Licencia de conducción y otras autorizaciones para conducir."},correct:"c",why:{a:"Es Título IV.",b:"Es Título V.",c:"Correcto: Anexo III.",d:"Es Anexo II."}},
{n:21,q:"El Anexo IV del Reglamento General de Conductores (RD 818/2009), se denomina:",o:{a:"Organización, desarrollo y criterios de calificación de las pruebas de control de conocimientos y de control de aptitudes y comportamientos.",b:"Personal examinador encargado de calificar las pruebas de control de aptitudes y comportamientos.",c:"Aptitudes psicofísicas requeridas para obtener o prorrogar la vigencia del permiso o licencia de conducción.",d:"Vehículos a utilizar en las pruebas de control de aptitudes y comportamientos."},correct:"c",why:{a:"Es Anexo VI.",b:"Es Anexo VIII.",c:"Correcto: Anexo IV.",d:"Es Anexo VII."}},
{n:22,q:"En el Reglamento General de Conductores (RD 818/2009), los códigos referidos a las adaptaciones, restricciones y otras limitaciones respecto de las personas, vehículos y de circulación que, en su caso, figuren en el permiso o licencia de conducción, se describen en:",o:{a:"Su Anexo I.",b:"Su Anexo II.",c:"Su Anexo III.",d:"Su Anexo IV."},correct:"a",why:{a:"✓ Respuesta oficial. No.",b:"⚠ Mi respuesta inicial (incorrecta): Correcto: Anexo II — Licencia de conducción y otras autorizaciones.",c:"No.",d:"No."}},
{n:23,q:"El Título IV de la Ley de Seguridad Vial (RDL 6/2015):",o:{a:"Se denomina \"Autorizaciones administrativas\".",b:"Tiene cuatro Capítulos.",c:"Abarca los artículos 59 a 73.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres."}},
{n:24,q:"El Título IV de la Ley de Seguridad Vial (RDL 6/2015), denominado \"Autorizaciones administrativas\", dedica a las autorizaciones en general:",o:{a:"Su Capítulo I.",b:"Su Capítulo II.",c:"Su Capítulo III.",d:"Su Capítulo IV."},correct:"a",why:{a:"Correcto: Cap.I.",b:"No.",c:"No.",d:"No."}},
{n:25,q:"Según el art.1 del Reglamento General de Conductores (RD 818/2009):",o:{a:"Los permisos y licencias de conducción son de otorgamiento y contenido reglados.",b:"Los permisos o licencias de conducción se podrán sustituir provisionalmente por autorizaciones temporales, cuando sea necesario.",c:"Ninguna persona podrá ser titular de más de un permiso o licencia de conducción expedido por un Estado miembro de la UE o por un Estado parte del Acuerdo sobre el Espacio Económico Europeo.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres."}},
{n:26,q:"Según el art.2 del Reglamento General de Conductores (RD 818/2009), los permisos y licencias de conducción, así como las autorizaciones administrativas que provisionalmente los sustituyan:",o:{a:"Serán expedidos por las Jefaturas Provinciales de Tráfico, con excepción de los que autorizan a conducir vehículos de las Fuerzas Armadas.",b:"Serán expedidos por las Jefaturas Provinciales de Tráfico, con excepción de los que autorizan a conducir vehículos de la Dirección General de Policía y de la Guardia Civil.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Correcto: ambas excepciones.",d:"Las dos son ciertas."}},
{n:27,q:"Según el art.33 del Reglamento General de Conductores (RD 818/2009), el permiso internacional para conducir se solicitará en el modelo oficial suscrito por el interesado, acompañando a la solicitud los documentos que se indican en el Anexo III y será expedido:",o:{a:"Por la Jefatura Provincial de Tráfico en la que se solicite.",b:"Por la Jefatura Provincial de Tráfico de Madrid.",c:"Por la Dirección General de Tráfico.",d:"Por el Ministerio de Asuntos Exteriores."},correct:"a",why:{a:"Correcto: JPT donde se solicite.",b:"No solo Madrid.",c:"No la DGT directamente.",d:"No Exteriores."}},
{n:28,q:"Según el Reglamento General de Conductores (RD 818/2009):",o:{a:"Todas las clases de permiso de conducción de que sea titular una persona deberán constar en un único documento, con expresión de las categorías de vehículos cuya conducción autorizan.",b:"Los conductores quedan obligados a estar en posesión y llevar consigo su permiso o licencia de conducción, así como cualquier otro documento o autorización que necesite para poder conducir.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son falsas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:29,q:"Según lo establecido en el art.1 del Reglamento General de Conductores (RD 818/2009):",o:{a:"La conducción de vehículos por vías y terrenos públicos exigirá haber obtenido previamente el permiso o licencia de conducción correspondiente.",b:"La concesión de los permisos y licencias de conducción correspondientes queda condicionada a la verificación de que los conductores reúnen los requisitos, conocimientos y aptitudes exigidos en dicho Reglamento.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son falsas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto.",d:"Las dos son ciertas."}},
{n:30,q:"De conformidad con lo establecido en el art.1.3. del Reglamento General de Conductores (RD 818/2009), las autorizaciones temporales que podrán sustituir provisionalmente los permisos y licencias de conducción:",o:{a:"Surtirán idénticos efectos a los del permiso o licencia de conducción al que sustituyan.",b:"Tendrán una validez de seis meses.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son falsas."},correct:"a",why:{a:"Correcto: mismos efectos.",b:"La validez es de tres meses, no seis.",c:"La b es falsa.",d:"La a es cierta."}},
{n:31,q:"Respecto a las autorizaciones temporales que podrán sustituir provisionalmente los permisos y licencias de conducción, señale la afirmación incorrecta:",o:{a:"Pueden descargarse en la aplicación informática de la DGT.",b:"Su formato se regula en la Instrucción DGT 12/C-144.",c:"Su validez está condicionada a que vayan acompañadas de un documento oficial de identificación.",d:"Su plazo de validez es de tres meses."},correct:"b",why:{a:"Cierto.",b:"La referencia de la Instrucción DGT no coincide con la oficial.",c:"Cierto.",d:"Cierto."}},
{n:32,q:"Según lo establecido en el art.1 del Reglamento General de Conductores (RD 818/2009):",o:{a:"Los conductores quedan obligados a estar en posesión y llevar consigo su permiso o licencia de conducción, así como cualquier otro documento o autorización que necesite para poder conducir.",b:"Los documentos acreditativos para conducir deben ser válidos, estar vigentes y deberán exhibirse ante los agentes de la autoridad que lo soliciten.",c:"Todas las clases de permiso de conducción de las que sea titular una persona deberán constar en un único documento con expresión de las categorías de vehículos cuya conducción autorizan.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres."}},
{n:33,q:"Los titulares de los permisos de conducción deberán sujetarse a las menciones, adaptaciones, restricciones y otras limitaciones respecto de las personas, vehículos o de circulación que, en su caso, figuren en el permiso o licencia de conducción de forma codificada, según se determina:",o:{a:"En el Anexo I del Reglamento General de Conductores (RD 818/2009).",b:"En el Anexo II del Reglamento General de Conductores (RD 818/2009).",c:"En el Anexo III del Reglamento General de Conductores (RD 818/2009).",d:"En el Anexo IV del Reglamento General de Conductores (RD 818/2009)."},correct:"a",why:{a:"✓ Respuesta oficial. No.",b:"⚠ Mi respuesta inicial (incorrecta): Correcto: Anexo II.",c:"No.",d:"No."}},
{n:34,q:"En España, el permiso de conducción por puntos se implantó mediante:",o:{a:"La ley 17/2005, de 19 de julio.",b:"La Ley 19/2006 de 11 de enero.",c:"El Real Decreto Legislativo 36/2005 de 11 de enero.",d:"El Real Decreto Legislativo 11/2006 de 19 de enero."},correct:"a",why:{a:"Correcto: Ley 17/2005.",b:"No.",c:"No.",d:"No."}},
{n:35,q:"De conformidad con lo establecido en el art.63.1 de la Ley de Seguridad Vial (RDL 6/2015), al titular de un permiso o licencia de conducción se le asignará un crédito inicial de:",o:{a:"10 puntos.",b:"12 puntos.",c:"15 puntos.",d:"8 puntos."},correct:"b",why:{a:"No.",b:"Correcto: 12 puntos.",c:"No.",d:"Solo en supuestos excepcionales."}},
{n:36,q:"Según el art.63.2 de la Ley de Seguridad Vial (RDL 6/2015), excepcionalmente, se asignará un crédito inicial de ocho puntos al titular de un permiso o licencia de conducción:",o:{a:"Que tenga una antigüedad no superior a tres años, salvo que ya fuera titular de otro permiso de conducción con aquella antigüedad.",b:"Que, tras perder su asignación total de puntos, ha obtenido nuevamente el permiso o la licencia de conducción.",c:"Las respuestas a y b son incorrectas.",d:"Las respuestas a y b son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Ambas son ciertas.",d:"Correcto: las dos."}},
{n:37,q:"Con respecto a la normativa reguladora del permiso de conducción por puntos, indique la afirmación correcta:",o:{a:"Los conductores no perderán, en ningún caso, más de ocho puntos por acumulación de infracciones en un solo día.",b:"El número de puntos inicialmente asignado se verá reducido por cada sanción firme en vía administrativa que se imponga por la comisión de infracciones graves o muy graves de las que se concretan e los anexos II y IV de la Ley de Seguridad Vial.",c:"La pérdida parcial de puntos supone la inhabilitación para conducir durante el periodo que reglamentariamente se determine.",d:"Cuando se pierden todos los puntos se produce la pérdida de vigencia de la autorización administrativa para conducir, sin necesidad de que la Jefatura Provincial de Tráfico correspondiente declare dicha pérdida de vigencia."},correct:"b",why:{a:"⚠ Mi respuesta inicial (incorrecta): Correcto: el límite diario es 8 puntos.",b:"✓ Respuesta oficial. Las infracciones que detraen puntos figuran en el Anexo II LSV (no «II y IV»).",c:"La pérdida parcial no inhabilita; sólo la total.",d:"La JPT debe declarar la pérdida de vigencia."}},
{n:38,q:"La pérdida total de los puntos asignados al permiso o licencia de conducción determina:",o:{a:"La pérdida de la vigencia de la autorización administrativa para conducir, que será declarada por resolución de la Jefatura Provincial de Tráfico y notificada al interesado.",b:"Que el interesado no puede obtener una nueva autorización administrativa para conducir hasta que transcurra un determinado periodo de tiempo.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:39,q:"Según establece el art.64.3 de la Ley de Seguridad Vial (RDL 6/2015), al permiso o licencia de conducción, cualquiera que sea su clase, le afectará:",o:{a:"La pérdida parcial o total de puntos.",b:"La recuperación de los puntos asignados.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto.",d:"Las dos son ciertas."}},
{n:40,q:"Con respecto al sistema de bonificación de puntos a los titulares de una autorización administrativa para conducir, indique la afirmación correcta:",o:{a:"Quienes mantengan la totalidad de los puntos por no haber sido sancionados en firme en vía administrativa, recibirán como bonificación dos puntos durante los tres primeros años, y un punto por los tres siguientes, pudiendo llegar a acumular un máximo de quince puntos.",b:"Quienes mantengan la totalidad de los puntos por no haber sido sancionados, recibirán como bonificación cuatro puntos durante los tres primeros años, y dos puntos por los tres siguientes, pudiendo llegar a acumular un máximo de dieciocho puntos",c:"Quienes mantengan la totalidad de los puntos por no haber sido sancionados, recibirán como bonificación tres puntos durante los tres primeros años, y un punto por los tres siguientes, pudiendo llegar a acumular un máximo de dieciséis puntos",d:"Todas las respuestas anteriores son incorrectas."},correct:"a",why:{a:"Correcto: 2 pts cada 3 años, luego 1 pt, máx 15.",b:"Cifras incorrectas.",c:"Cifras incorrectas.",d:"La a es correcta."}},
{n:41,q:"Para obtener un nuevo permiso de conducción, una vez perdida la vigencia del anterior por haber agotado totalmente el crédito de puntos:",o:{a:"Es necesario realizar y superar con aprovechamiento un curso de sensibilización y reeducación vial y posteriormente superar la prueba de control de conocimientos regulada en el Reglamento General de Conductores.",b:"Deben superarse, en el pazo máximo de un año, las pruebas que reglamentariamente se determinen.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Correcto: curso + prueba de control.",b:"No se exige ese plazo de un año.",c:"La b no es cierta.",d:"La a sí lo es."}},
{n:42,q:"Según lo establecido en la Ley de Seguridad Vial (RDL 6/2015), respecto al crédito y/o pérdida de puntos asignados al titular de un permiso o licencia de conducción, indique la afirmación incorrecta:",o:{a:"El crédito de puntos es único para todas las autorizaciones administrativas de las que sea titular el conductor.",b:"Los conductores no perderán más de ocho puntos por acumulación de infracciones en un solo día, salvo que concurra alguna de las infracciones de carácter grave o muy grave previstas en los párrafos a), c), d), e), f), g), e i) del artículo 77 de dicha Ley.",c:"Transcurridos dos años sin haber sido sancionado en firme en vía administrativa por infracciones que conlleven la pérdida de puntos, el titular del permiso recuperará la totalidad del crédito inicial de doce puntos.",d:"La pérdida de puntos solo se producirá cuando el hecho del que se deriva la detracción se produzca mediante la conducción de un vehículo para el que se exija permiso o licencia de conducción."},correct:"b",why:{a:"Cierto.",b:"✓ Respuesta oficial. Cierto.",c:"⚠ Mi respuesta inicial (incorrecta): El plazo es 2 años para infracciones graves, pero 3 años para muy graves; la generalización es inexacta.",d:"Cierto."}},
{n:43,q:"Un ciclista, titular de un permiso de conducción de la clase A, es sancionado por conducir la bicicleta superando las tasas máximas establecidas de alcohol en aire espirado. En este caso:",o:{a:"Le serán detraídos 6 puntos de su permiso de conducción.",b:"Le serán detraídos 4 puntos de su permiso de conducción.",c:"No se producirá detracción de puntos de su permiso de conducción porque está desarrollando una actividad para la que no precisa permiso de conducción.",d:"No se producirá detracción de puntos de su permiso de conducción porque la conducción de bicicletas superando las tasas máximas de alcoholemia no constituye infracción administrativa."},correct:"c",why:{a:"No hay detracción.",b:"No hay detracción.",c:"Correcto: la pérdida sólo se produce si se exige permiso para el vehículo conducido.",d:"Sí es infracción administrativa, pero no detrae puntos."}},
{n:44,q:"Los conductores no perderán más de ocho puntos por acumulación de infracciones en un solo día, salvo que concurra alguna de las infracciones de carácter muy grave previstas en los párrafos a), c), d), e), f), g), h) e i) del artículo 77 de la Ley de Seguridad Vial, en cuyo caso:",o:{a:"Perderán el número total de puntos que les correspondan.",b:"Perderán durante dos años el permiso o licencia de conducción que posean.",c:"Podrán perder el permiso o licencia de conducción durante un periodo de dos años.",d:"Todas las respuestas anteriores son incorrectas."},correct:"a",why:{a:"Correcto: pierden el total de puntos correspondientes.",b:"No es pérdida temporal del permiso.",c:"No es esa la consecuencia.",d:"La a es correcta."}},
{n:45,q:"El titular de un permiso o licencia de conducción que haya perdido una parte del crédito inicial de puntos asignado, podrá optar a su recuperación parcial:",o:{a:"Hasta un máximo de seis puntos.",b:"Por una sola vez cada dos años.",c:"Realizando y superando con aprovechamiento un curso de sensibilización y reeducación vial.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres."}},
{n:46,q:"Según lo establecido en el art.65.4 de la Ley de Seguridad vial (RDL 6/2015), el titular de un permiso o licencia de conducción que haya perdido una parte del crédito inicial de puntos asignado, deberá superar un curso de sensibilización y reeducación vial, cuya duración será:",o:{a:"Como máximo de veinte horas.",b:"En todo caso, como máximo de quince horas.",c:"Como máximo de treinta horas.",d:"En todo caso, como máximo de doce horas."},correct:"b",why:{a:"No.",b:"Correcto: máx. 15 horas para recuperación parcial.",c:"30 horas es para recuperación total.",d:"No."}},
{n:47,q:"Con respecto a los cursos para recuperar la pérdida parcial de puntos del permiso o licencia de conducción, indique la afirmación correcta.",o:{a:"Los conductores profesionales pueden realizar este tipo de cursos con frecuencia anual.",b:"Como regla general, el número máximo de puntos que se puede recuperar de esta forma es de seis puntos cada año.",c:"Para conductores profesionales, el número máximo de puntos que se pueden recuperar es de doce cada año.",d:"Todos los conductores, profesionales y no profesionales, podrán realizar estos cursos, como máximo, una vez cada dos años y el número de puntos a recuperar será de un máximo de cuatro, para conductores no profesionales, y de un máximo de seis para conductores profesionales."},correct:"a",why:{a:"Correcto: los profesionales pueden hacerlo anualmente; los no profesionales, cada 2 años.",b:"La regla general es 6 puntos cada 2 años, no cada año.",c:"No es 12 puntos.",d:"Cifras incorrectas (no profesionales: 6 puntos; profesionales: anual)."}},
{n:48,q:"De conformidad con la normativa reguladora del permiso de conducción por puntos, indique la afirmación correcta:",o:{a:"Una vez que se han perdido todos los puntos pueden realizarse cursos para la recuperación parcial de los mismos (hasta 4 puntos, cada dos años).",b:"Una vez que se han perdido todos los puntos pueden realizarse cursos para la recuperación parcial de los mismos (hasta 4 puntos, cada dos años para conductores no profesionales y hasta 6 puntos cada año para conductores profesionales).",c:"Una vez que se han perdido todos los puntos pueden realizarse cursos para la recuperación parcial de los mismos (hasta 2 puntos, cada dos años para conductores no profesionales y hasta 4 puntos cada año para conductores profesionales).",d:"Ninguna de las respuestas anteriores es correcta."},correct:"d",why:{a:"Tras pérdida total no procede recuperación parcial.",b:"Tras pérdida total no procede recuperación parcial.",c:"Tras pérdida total no procede recuperación parcial.",d:"Correcto: perdida la totalidad, la recuperación es por curso + prueba de control, no parcial."}},
{n:49,q:"El titular de un permiso o licencia de conducción que haya perdido una parte del crédito inicial de puntos asignado, podrá optar a su recuperación parcial, hasta un máximo de seis puntos, por una sola vez cada dos años, realizando y superando con aprovechamiento un curso de sensibilización y reeducación vial:",o:{a:"Correcto, con la excepción de los conductores profesionales que podrán realizar el citado curso cada seis meses.",b:"Correcto, con la excepción de los conductores profesionales que podrán realizar el citado curso con frecuencia anual.",c:"Correcto, con la excepción de los conductores profesionales que podrán realizar el citado curso con frecuencia de dieciocho meses.",d:"Incorrecto."},correct:"b",why:{a:"La excepción es anual, no semestral.",b:"Correcto: los conductores profesionales, cada año.",c:"No es 18 meses.",d:"Sí es correcto con la salvedad de la b."}},
{n:50,q:"La Jefatura Provincial de Tráfico declarará la pérdida de vigencia del permiso o licencia de conducción, cuando su titular haya perdido la totalidad de los puntos asignados y una vez constatada tal pérdida:",o:{a:"La administración lo notificará al interesado en el plazo de 15 días.",b:"Su titular no podrá obtener un nuevo permiso o licencia hasta transcurrido un año desde la notificación del acuerdo.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"✓ Respuesta oficial. El plazo no es de 15 días.",b:"El plazo no es de un año (es 6 meses, 3 si profesional).",c:"Las dos cifras son inexactas.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: ambas cifras son incorrectas."}},
{n:51,q:"Respecto a la pérdida de vigencia del permiso o licencia de conducción, cuando su conductor haya perdido la totalidad de los puntos asignados y una vez constatada la pérdida, indique la afirmación incorrecta:",o:{a:"La administración lo notificará al interesado en el plazo de veinte días.",b:"Su titular no podrá obtener un nuevo permiso o licencia hasta transcurridos seis meses desde la notificación del acuerdo, salvo que se trate de conductores profesionales, en cuyo caso el plazo se reduce a tres meses.",c:"Si durante los tres años siguientes a la obtención del nuevo permiso o licencia de conducción fuera acordada su pérdida de vigencia por haber perdido nuevamente la totalidad de los puntos asignados, no se podrá obtener un nuevo permiso o licencia de conducción hasta transcurridos doce meses desde la notificación del acuerdo. Este plazo se reducirá a seis meses en el caso de conductores profesionales.",d:"Su titular podrá recuperar su permiso o licencia realizando y superando con aprovechamiento un curso de sensibilización y reeducación vial y posteriormente superar la prueba de control regulada en el Reglamento General de Conductores."},correct:"a",why:{a:"El plazo de notificación no es 20 días.",b:"Correcto.",c:"Correcto.",d:"Correcto."}},
{n:52,q:"Los cursos de sensibilización y reeducación vial para los titulares de un permiso o licencia de conducción se regulan:",o:{a:"En el art.60.2 de la Ley de Seguridad Vial (RDL 6/2015).",b:"En el Capítulo I, Sección 2ª, del Título I del Reglamento General de Conductores (RD 818/2009).",c:"En la Orden INT/914/2024, de 2 de septiembre",d:"En toda la legislación citada en las respuestas anteriores."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"✓ Respuesta oficial. Parcial.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: las tres normas regulan los cursos."}},
{n:53,q:"La Orden INT/914/2024, de 2 de septiembre, por la que se regulan los cursos de sensibilización y reeducación vial para los titulares de un permiso o licencia de conducción:",o:{a:"Deroga la Orden INT/2596/2005, de 28 de julio.",b:"Entró en vigor el día 04-11-2024.",c:"Consta de 10 artículos.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres."}},
{n:54,q:"Respecto a los cursos de sensibilización y reeducación vial para los titulares de un permiso o licencia de conducción, indique la afirmación incorrecta:",o:{a:"Son de dos tipos: cursos para la recuperación parcial de puntos y cursos de recuperación del permiso o la licencia de conducción.",b:"Tienen una duración máxima de 20 horas.",c:"El tiempo de su duración se distribuirá en una parte común y otra específica.",d:"Contarán con la participación de asociaciones de víctimas de accidentes de tráfico, siendo obligatoria la intervención de víctimas en los mismos."},correct:"b",why:{a:"Cierto.",b:"La duración máxima no es 20 horas (parcial 15h; recuperación 30h).",c:"Cierto.",d:"Cierto."}},
{n:55,q:"Según lo establecido en el art.3 de la Orden INT/914/2024, la realización y superación con aprovechamiento de los cursos de sensibilización y reeducación vial para los titulares de un permiso o licencia de conducción:",o:{a:"Permitirán al titular de la autorización para conducir la recuperación de cuatro puntos, sin que en ningún caso se puedan recuperar más puntos de los que se hubieran perdido.",b:"Permitirán la recuperación de un permiso o licencia de conducción de la misma clase de la que se fuera titular, siempre que posteriormente se supere la prueba de control de conocimientos referida en el art.10 de la Orden INT/914/2024.",c:"Las respuestas a y b son incorrectas.",d:"Las respuestas a y b son correctas."},correct:"b",why:{a:"Cierto (con el matiz «sin que en ningún caso se puedan recuperar más puntos de los perdidos»).",b:"✓ Respuesta oficial. Cierto.",c:"Ambas son ciertas.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: ambas."}},
{n:56,q:"Según la Orden INT/914/2024, los cursos de sensibilización y reeducación vial para la recuperación parcial de puntos tendrán una duración:",o:{a:"Máxima de 30 horas.",b:"Mínima de 20 horas.",c:"Máxima de 20 horas.",d:"Mínima de 10 horas."},correct:"d",why:{a:"30h es para recuperación total.",b:"No es duración mínima.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: máx. 20 horas para recuperación parcial (según la nueva Orden).",d:"✓ Respuesta oficial. No es ese parámetro."}},
{n:57,q:"Según la Orden INT/914/2024, los cursos de sensibilización y reeducación vial para la recuperación del permiso o licencia por agotamiento del crédito de puntos tendrán una duración:",o:{a:"Máxima de 30 horas.",b:"Mínima de 20 horas.",c:"Máxima de 20 horas.",d:"Mínima de 10 horas."},correct:"b",why:{a:"⚠ Mi respuesta inicial (incorrecta): Correcto: máx. 30 horas para la recuperación total.",b:"✓ Respuesta oficial. No es mínima.",c:"20h es para recuperación parcial.",d:"No es ese parámetro."}},
{n:58,q:"El titular de un permiso o licencia de conducción condenado a la pena de privación del derecho a conducir, una vez cumplida la condena, podrá obtener un permiso o licencia de la misma clase...",o:{a:"Si la condena es por tiempo superior a dos años, lo podrá obtener conforme al procedimiento previsto para cuando se produce la pérdida total de los puntos asignados.",b:"Si la condena es por tiempo superior a dos años, el nuevo permiso tendrá un saldo de 8 puntos.",c:"Si la condena es igual o inferior a 2 años, para volver a conducir bastará con superar el curso de sensibilización y reeducación vial.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres son correctas."}},
{n:59,q:"Según lo establecido en el art.10 de la Orden INT/914/2024, la prueba de control de conocimientos prevista en el Reglamento General de Conductores, para volver a obtener la autorización administrativa para conducir, deben realizarla:",o:{a:"Los titulares de permisos y licencias de conducción, cuya pérdida de vigencia haya sido declarada tras la pérdida del crédito total de puntos asignado y hayan superado previamente con aprovechamiento el curso de sensibilización y reeducación vial.",b:"Los condenados por sentencia judicial firme con privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a dos años, que hayan superado previamente con aprovechamiento el curso de sensibilización y reeducación vial.",c:"Los citados en las respuestas a y b.",d:"Todas las respuestas anteriores son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Correcto: ambos grupos deben realizar la prueba.",d:"Las dos son ciertas."}},
{n:60,q:"Según lo establecido en el art.10 de la Orden INT/914/2024, quienes están obligados a realizar la prueba de control de conocimientos prevista en el Reglamento General de Conductores, para volver a obtener la autorización administrativa para conducir, deben realizarla:",o:{a:"En el plazo máximo de tres años desde la fecha de superación con aprovechamiento del curso de sensibilización y reeducación vial.",b:"En el plazo máximo de dos años desde la fecha de superación con aprovechamiento del curso de sensibilización y reeducación vial.",c:"En el plazo máximo de un año desde la fecha de superación con aprovechamiento del curso de sensibilización y reeducación vial.",d:"En el plazo máximo de seis meses desde la fecha de superación con aprovechamiento del curso de sensibilización y reeducación vial."},correct:"b",why:{a:"No es 3 años.",b:"Correcto: máx. 2 años desde la superación del curso.",c:"No es 1 año.",d:"No es 6 meses."}},
{n:61,q:"Según lo establecido en el art.10 de la Orden INT/914/2024, respecto a la prueba a realizar tras el curso de recuperación del permiso o licencia de conducción, indique la afirmación incorrecta:",o:{a:"Debe realizarse en el plazo máximo de tres años desde la fecha de superación con aprovechamiento del curso de sensibilización y reeducación vial",b:"Aquellos que no superen la prueba en primera convocatoria, podrán presentarse nuevamente hasta un máximo de dos ocasiones, debiendo realizar previamente en cada una de ellas un ciclo formativo de cuatro horas de duración.",c:"El ciclo formativo que han de realizar quienes no superen la prueba en primera convocatoria, que tendrá el mismo contenido que la parte específica, podrá realizarse de forma online, siempre que se utilice una plataforma que cuente con un registro de conexiones y actividad en el que se identifique a los alumnos que participan y deje constancia de la fecha y el tiempo de conexión.",d:"Deben realizarla los condenados por sentencia judicial firme con privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a dos años, que hayan superado previamente con aprovechamiento el curso de sensibilización y reeducación vial."},correct:"a",why:{a:"El plazo máximo es de 2 años, no 3.",b:"Correcto.",c:"Correcto.",d:"Correcto."}},
{n:62,q:"Según establece el art.71 de la Ley de Seguridad Vial (RDL 6/2015), respecto a los cursos de sensibilización y reeducación vial, indique la afirmación incorrecta:",o:{a:"Tendrán la duración y el contenido que se determinen por el Ministro del Interior.",b:"Correrán a cargo de los interesados.",c:"Su duración será, como máximo, de 30 horas, cuando se pretenda obtener un nuevo permiso o licencia de conducción.",d:""},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"✓ Respuesta oficial. Cierto.",d:"⚠ Mi respuesta inicial (incorrecta): Opción no visible en la página (continúa en pág. siguiente)."}},
{n:63,q:"Leticia ha sido condenada por sentencia judicial firme a la pena de privación del derecho a conducir por tiempo de 18 meses. Una vez cumplida la condena puede volver a conducir:",o:{a:"Siempre que supere con aprovechamiento el curso de sensibilización y reeducación vial previsto para los casos de pérdida total de los puntos asignados al permiso o licencia y, posteriormente, supere las pruebas que reglamentariamente se determinen.",b:"Siempre que realice con aprovechamiento el curso de sensibilización y reeducación vial previsto para la recuperación parcial de puntos y, posteriormente, supere las pruebas que reglamentariamente se determinen.",c:"Siempre que supere con aprovechamiento el curso de sensibilización y reeducación vial previsto para los casos de pérdida total de los puntos asignados al permiso o licencia.",d:"Siempre que realice con aprovechamiento el curso de sensibilización y reeducación vial previsto para la recuperación parcial de puntos."},correct:"d",why:{a:"La condena ≤2 años solo exige el curso, no prueba adicional.",b:"No es el curso de recuperación parcial.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: ≤2 años → solo el curso de pérdida total sin prueba posterior.",d:"✓ Respuesta oficial. No es el de recuperación parcial."}},
{n:64,q:"Alicia ha sido condenada por sentencia judicial firme a la pena de privación del derecho a conducir por tiempo de tres años. Una vez cumplida la condena puede volver a conducir:",o:{a:"Siempre que supere con aprovechamiento el curso de sensibilización y reeducación vial previsto para los casos de pérdida total de los puntos asignados al permiso o licencia y, posteriormente, supere la prueba de control de conocimientos referida en el art.10 de la Orden INT/914/2024.",b:"Siempre que realice con aprovechamiento el curso de sensibilización y reeducación vial previsto para la recuperación parcial de puntos y, posteriormente, supere las pruebas que reglamentariamente se determinen.",c:"Siempre que supere con aprovechamiento el curso de sensibilización y reeducación vial previsto para los casos de pérdida total de los puntos asignados al permiso o licencia.",d:"Siempre que realice con aprovechamiento el curso de sensibilización y reeducación vial previsto para la recuperación parcial de puntos."},correct:"a",why:{a:"Correcto: >2 años → curso de pérdida total + prueba de control del art.10 Orden INT/914/2024.",b:"No es parcial.",c:"Falta la prueba de control.",d:"No es parcial."}},
{n:65,q:"Conducir con una tasa de alcohol en aire espirado superior a 0,50 mg/l. Indique cuantos puntos se detraen, en general, del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"a",why:{a:"Correcto: alcohol >0,50 mg/l → 6 puntos (Anexo II LSV).",b:"Corresponde a 0,25-0,50 mg/l.",c:"No.",d:"No."}},
{n:66,q:"Conducir con una tasa de alcohol en aire espirado superior a 0,25mg/l hasta 0,50 mg/l. Indique cuantos puntos se detraen, en general, del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"b",why:{a:"6 puntos es para >0,50 mg/l.",b:"Correcto: 0,25-0,50 mg/l → 4 puntos.",c:"No.",d:"No."}},
{n:67,q:"Conducir con una tasa de alcohol en aire espirado superior a 0,30 mg/l, siendo conductor profesional o con menos de dos años de antigüedad en el permiso. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"a",why:{a:"Correcto: >0,30 mg/l para profesional/novato equivale al tramo >0,50 general → 6 puntos.",b:"4 pts es para el tramo 0,15-0,30 mg/l profesional/novato.",c:"No.",d:"No."}},
{n:68,q:"Sara, que obtuvo el permiso de conducción hace 18 meses, es denunciada por conducir un turismo con una tasa de alcohol en aire espirado de 0,30 mg/litro. En el supuesto de que sea sancionada administrativamente ¿Cuántos puntos perderá de su permiso de conducción?",o:{a:"6.",b:"4.",c:"3.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"b",why:{a:"6 pts es para >0,30 mg/l.",b:"Correcto: Sara (<2 años) a 0,30 mg/l está en el tramo 0,15-0,30 mg/l → 4 puntos.",c:"No.",d:"La b es correcta."}},
{n:69,q:"Conducir con presencia de drogas en el organismo. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"a",why:{a:"Correcto: drogas → 6 puntos (Anexo II LSV).",b:"No.",c:"No.",d:"No."}},
{n:70,q:"Conducir con una tasa de alcohol en aire espirado superior a 0,15 mg/l hasta 0,30 mg/l, siendo conductor profesional o con menos de dos años de antigüedad en el permiso. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"b",why:{a:"6 pts es para el tramo superior.",b:"Correcto: 0,15-0,30 mg/l profesional/novato → 4 puntos.",c:"No.",d:"No."}},
{n:71,q:"Patricia ha sido denunciada por conducir un taxi con una tasa de alcohol en aire espirado de 0,40 mg/litro. En el supuesto de que sea sancionada administrativamente ¿Cuántos puntos perderá de su permiso de conducción?",o:{a:"6.",b:"4.",c:"3.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"a",why:{a:"Correcto: Patricia es conductora profesional (taxi). 0,40 mg/l > 0,30 mg/l → 6 puntos.",b:"No.",c:"No.",d:"La a es correcta."}},
{n:72,q:"Susana es denunciada por conducir una motocicleta con una tasa de alcohol en aire espirado de 0,56 mg/litro. En el supuesto de que sea sancionada administrativamente ¿Cuántos puntos perderá de su permiso de conducción?",o:{a:"6.",b:"4.",c:"3.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"a",why:{a:"Correcto: 0,56 mg/l > 0,50 mg/l → 6 puntos.",b:"No.",c:"No.",d:"La a es correcta."}},
{n:73,q:"Nuria es denunciada por conducir una motocicleta con presencia de drogas en el organismo. En el supuesto de que sea sancionada administrativamente ¿Cuántos puntos perderá de su permiso de conducción?",o:{a:"6.",b:"4.",c:"3.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"a",why:{a:"Correcto: drogas → 6 puntos.",b:"No.",c:"No.",d:"La a es correcta."}},
{n:74,q:"Conducir un vehículo con un permiso o licencia de conducción que no habilita para ello. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"b",why:{a:"⚠ Mi respuesta inicial (incorrecta): Correcto: conducir sin permiso habilitante → 6 puntos.",b:"✓ Respuesta oficial. No.",c:"No.",d:"Sí detraen."}},
{n:75,q:"Adelantar poniendo en peligro o entorpeciendo a ciclistas o sin dejar la separación mínima de 1,5 metros. Indique cuantos puntos se detraen del permiso de conducción por la comisión de alguna de estas infracciones.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"a",why:{a:"✓ Respuesta oficial. No.",b:"⚠ Mi respuesta inicial (incorrecta): Correcto: adelantamiento peligroso a ciclistas → 4 puntos.",c:"No.",d:"No."}},
{n:76,q:"Por infracciones de carácter grave como consecuencia de excesos de velocidad, el número de puntos a detraer del permiso o licencia de conducción, dependiendo de la velocidad a la que se circula y de los límites de velocidad de la vía, puede ser:",o:{a:"2 o 4 puntos.",b:"2, 3 o 4 puntos.",c:"2, 4 o 6 puntos.",d:"4 o 6 puntos."},correct:"c",why:{a:"⚠ Mi respuesta inicial (incorrecta): Correcto: infracciones graves de velocidad → 2 o 4 puntos según el exceso.",b:"No incluye 3 puntos para velocidad.",c:"✓ Respuesta oficial. 6 puntos es para muy graves.",d:"2 puntos también es posible."}},
{n:77,q:"Por infracciones de carácter muy grave como consecuencia de excesos de velocidad, el número de puntos a detraer del permiso o licencia de conducción, dependiendo de la velocidad a la que se circula y de los límites de velocidad de la vía, puede ser:",o:{a:"6 puntos en todo caso.",b:"2, 3 o 4 puntos.",c:"2, 4 o 6 puntos.",d:"4 o 6 puntos."},correct:"a",why:{a:"✓ Respuesta oficial. No es siempre 6.",b:"No.",c:"Las muy graves no son 2 puntos.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: muy graves de velocidad → 4 o 6 puntos según exceso y tipo de vía."}},
{n:78,q:"Conducir bajo los efectos de medicamentos. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"d",why:{a:"No.",b:"No.",c:"No.",d:"Correcto: conducir bajo efectos de medicamentos no figura como infracción con detracción específica de puntos en el Anexo II LSV."}},
{n:79,q:"Arrojar a la vía o a sus inmediaciones objetos que puedan producir incendios o accidentes de circulación. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"a",why:{a:"✓ Respuesta oficial. No.",b:"No.",c:"No.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: esta conducta no aparece en el Anexo II LSV como infracción con detracción de puntos."}},
{n:80,q:"Incumplir las disposiciones legales sobre adelantamiento, poniendo en peligro o entorpeciendo a quienes circulen en sentido contrario. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"b",why:{a:"No.",b:"Correcto: adelantamiento peligroso contra sentido → 4 puntos.",c:"No.",d:"Sí detraen."}},
{n:81,q:"Adelantar en lugares o circunstancias de visibilidad reducida. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"b",why:{a:"No.",b:"Correcto: adelantamiento en visibilidad reducida → 4 puntos.",c:"No.",d:"Sí detraen."}},
{n:82,q:"Parar en un carril destinado a la circulación del transporte público urbano. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6",b:"4",c:"3",d:"Ninguno."},correct:"d",why:{a:"No.",b:"No.",c:"No.",d:"Correcto: parar en carril bus no figura en el Anexo II LSV con detracción de puntos."}},
{n:83,q:"Incumplir la obligación de someterse a las pruebas de detección de alcohol en el organismo. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"a",why:{a:"Correcto: negativa a prueba de alcohol → 6 puntos.",b:"No.",c:"No.",d:"No."}},
{n:84,q:"Conducir de forma negligente, creando un riesgo cierto y relevante para los otros usuarios de la vía. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"d",why:{a:"6 es para conducción temeraria.",b:"No.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: negligente con riesgo relevante → 3 puntos.",d:"✓ Respuesta oficial. Sí detraen."}},
{n:85,q:"No mantener la distancia de seguridad con el vehículo que le precede. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"b",why:{a:"No.",b:"✓ Respuesta oficial. No.",c:"No.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: no mantener distancia de seguridad no aparece en el Anexo II LSV con detracción de puntos."}},
{n:86,q:"Circular sin el alumbrado preceptivo, cuando resulta obligatorio conforme a lo establecido en las normas legales o reglamentarias. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"d",why:{a:"No.",b:"No.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: circular sin alumbrado preceptivo → 3 puntos.",d:"✓ Respuesta oficial. Sí detraen."}},
{n:87,q:"Raúl es denunciado cuando circula con una bicicleta por una autopista. En el caso que sea sancionado administrativamente ¿Cuántos puntos perderá de su permiso de conducción?",o:{a:"6.",b:"4.",c:"3.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"d",why:{a:"No.",b:"No.",c:"No.",d:"Correcto: conducir una bicicleta no requiere permiso de conducción, por lo que no hay detracción de puntos del permiso."}},
{n:88,q:"Conducir de forma temeraria. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"a",why:{a:"Correcto: conducción temeraria → 6 puntos.",b:"No.",c:"No.",d:"No."}},
{n:89,q:"Incumplir la obligación de detenerse ante la señal de stop. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"b",why:{a:"No.",b:"Correcto: no detenerse ante señal de stop → 4 puntos.",c:"No.",d:"Sí detraen."}},
{n:90,q:"Conducir un vehículo utilizando mecanismos de detección de radares o cenemómetros. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"c",why:{a:"No.",b:"No.",c:"Correcto: uso de detectores de radar → 3 puntos.",d:"No."}},
{n:91,q:"Conducir teniendo prohibido el uso del vehículo que se conduce. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"b",why:{a:"⚠ Mi respuesta inicial (incorrecta): Correcto: conducir con uso del vehículo prohibido → 6 puntos.",b:"✓ Respuesta oficial. No.",c:"No.",d:"No."}},
{n:92,q:"Utilizar, sujetando con la mano, dispositivos de telefonía móvil mientras se conduce. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"a",why:{a:"Correcto: uso manual de móvil → 6 puntos (tras la reforma 2021).",b:"No.",c:"Era 3 antes de la reforma; ahora son 6.",d:"Sí detraen."}},
{n:93,q:"Lorenzo es denunciado por conducir un turismo por una vía urbana mientras mantiene una conversación usando manualmente su teléfono móvil. En el caso de que sea sancionado administrativamente ¿Cuántos puntos perderá de su permiso de conducción?",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"c",why:{a:"⚠ Mi respuesta inicial (incorrecta): Correcto: uso manual de móvil → 6 puntos.",b:"No.",c:"✓ Respuesta oficial. No.",d:"Sí detraen."}},
{n:94,q:"Circular en sentido contrario al establecido. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"a",why:{a:"✓ Respuesta oficial. No.",b:"⚠ Mi respuesta inicial (incorrecta): Correcto: circular en sentido contrario → 4 puntos.",c:"No.",d:"No."}},
{n:95,q:"Realizar la maniobra de marcha atrás en autopistas. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"b",why:{a:"No.",b:"Correcto: marcha atrás en autopista → 4 puntos.",c:"No.",d:"Sí detraen."}},
{n:96,q:"Conducir un vehículo participando en una competición o carrera no autorizada. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"a",why:{a:"Correcto: participar en carrera no autorizada → 6 puntos.",b:"No.",c:"No.",d:"Sí detraen."}},
{n:97,q:"No hacer uso, o no hacerlo de forma adecuada, del cinturón de seguridad, sistemas de retención infantil, casco y demás elementos de protección obligatorios. Indique cuantos puntos se detraen del permiso de conducción por la comisión de alguna de estas infracciones.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"b",why:{a:"No.",b:"✓ Respuesta oficial. No.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: no usar cinturón/casco/retención → 3 puntos.",d:"No."}},
{n:98,q:"Efectuar un cambio de sentido incumpliendo las disposiciones recogidas en la legislación de tráfico o en sus normas reglamentarias. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"c",why:{a:"No.",b:"⚠ Mi respuesta inicial (incorrecta): Correcto: cambio de sentido ilegal → 4 puntos.",c:"✓ Respuesta oficial. No.",d:"No."}},
{n:99,q:"Estacionar en una curva. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"d",why:{a:"No.",b:"No.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: estacionar/parar en curva → 3 puntos.",d:"✓ Respuesta oficial. Sí detraen."}},
{n:100,q:"No respetar las señales de los agentes de la autoridad encargados de la vigilancia del tráfico. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"b",why:{a:"No.",b:"Correcto: no respetar señales de agentes → 4 puntos.",c:"No.",d:"No."}},
{n:101,q:"Parar en un cambio de rasante. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"d",why:{a:"No.",b:"No.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: parar en cambio de rasante → 3 puntos.",d:"✓ Respuesta oficial. Sí detraen."}},
{n:102,q:"No hacer uso del cinturón de seguridad. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"b",why:{a:"No.",b:"✓ Respuesta oficial. No.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: no usar cinturón → 3 puntos.",d:"Sí detraen."}},
{n:103,q:"Realizar la maniobra de marcha atrás en una autovía. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"b",why:{a:"No.",b:"Correcto: marcha atrás en autovía → 4 puntos.",c:"No.",d:"No."}},
{n:104,q:"Parar en un túnel. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6",b:"4",c:"3",d:"Ninguno."},correct:"d",why:{a:"No.",b:"No.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: parar en túnel → 3 puntos.",d:"✓ Respuesta oficial. Sí detraen."}},
{n:105,q:"Incumplir la obligación de detenerse ante un semáforo con luz roja encendida. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"b",why:{a:"No.",b:"Correcto: no detenerse ante semáforo en rojo → 4 puntos.",c:"No.",d:"Sí detraen."}},
{n:106,q:"Conducir vehículos que llevan instalados inhibidores de radar o cinemómetros u otros mecanismos encaminados a interferir en el correcto funcionamiento de los sistemas de vigilancia del tráfico. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"a",why:{a:"Correcto: llevar inhibidores (jammers) → 6 puntos.",b:"No.",c:"Los meros detectores son 3 pts; los inhibidores son 6.",d:"Sí detraen."}},
{n:107,q:"Un conductor colabora de forma necesaria en la puesta en funcionamiento de un elemento que altera el normal funcionamiento del tacógrafo. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"a",why:{a:"Correcto: colaborar en alteración del tacógrafo → 6 puntos.",b:"No.",c:"No.",d:"Sí detraen."}},
{n:108,q:"Conducir incumpliendo las disposiciones legales sobre preferencia de paso. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"b",why:{a:"No.",b:"Correcto: incumplir preferencia de paso → 4 puntos.",c:"No.",d:"No."}},
{n:109,q:"No respetar las señales o las órdenes de la autoridad encargada de la regulación, ordenación, gestión, vigilancia y disciplina del tráfico, o de sus agentes.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"b",why:{a:"No.",b:"Correcto: no respetar órdenes de la autoridad de tráfico → 4 puntos.",c:"No.",d:"No."}},
{n:110,q:"Un conductor colabora de forma necesaria en la puesta en funcionamiento de un elemento que altera el normal funcionamiento del limitador de velocidad. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"a",why:{a:"Correcto: colaborar en alteración del limitador de velocidad → 6 puntos.",b:"No.",c:"No.",d:"Sí detraen."}},
{n:111,q:"Incumplir la obligación de detenerse ante una señal de ceda el paso. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"b",why:{a:"No.",b:"Correcto: no ceder el paso → 4 puntos.",c:"No.",d:"Sí detraen."}},
{n:112,q:"Conducir utilizando manualmente el sistema de navegación del vehículo o cualquier otro medio de comunicación. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"c",why:{a:"6 pts es para el teléfono móvil sujetado con la mano.",b:"No.",c:"Correcto: usar manualmente el GPS/navegación → 3 puntos.",d:"Sí detraen."}},
{n:113,q:"No hacer uso del sistema de retención infantil. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"b",why:{a:"No.",b:"✓ Respuesta oficial. No.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: no retención infantil → 3 puntos.",d:"Sí detraen."}},
{n:114,q:"Conducir un vehículo teniendo suspendida la autorización administrativa para conducir. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"b",why:{a:"⚠ Mi respuesta inicial (incorrecta): Correcto: conducir con permiso suspendido → 6 puntos.",b:"✓ Respuesta oficial. No.",c:"No.",d:"Sí detraen."}},
{n:115,q:"Incumplir la obligación de someterse a las pruebas de detección de la presencia de drogas en el organismo. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"a",why:{a:"Correcto: negativa a prueba de drogas → 6 puntos.",b:"No.",c:"No.",d:"Sí detraen."}},
{n:116,q:"Conducir un vehículo utilizando cualquier tipo de casco de audio o auricular conectado a un aparato reproductor o receptor de sonido. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"c",why:{a:"No.",b:"No.",c:"Correcto: usar auriculares conduciendo → 3 puntos.",d:"Sí detraen."}},
{n:117,q:"Exceder en más de un 50% los tiempos de conducción establecidos en la legislación sobre transporte terrestre. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"a",why:{a:"✓ Respuesta oficial. No.",b:"No.",c:"No.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: exceder tiempos de conducción en transporte terrestre no figura como infracción con detracción de puntos en el Anexo II LSV."}},
{n:118,q:"Minorar en más de un 50% los tiempos de descanso establecidos en la legislación sobre transporte terrestre. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"2."},correct:"a",why:{a:"✓ Respuesta oficial. No.",b:"No.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: reducir tiempos de descanso de transporte terrestre en >50% → 3 puntos (Anexo II LSV).",d:"No."}},
{n:119,q:"Conducir utilizando dispositivos que disminuyan la atención permanente a la conducción, o manteniendo ajustado entre el casco y la cabeza del usuario dispositivos de telefonía móvil mientras se conduce. Indique cuantos puntos se detraen del permiso de conducción por la comisión de esta infracción.",o:{a:"6.",b:"4.",c:"3.",d:"Ninguno."},correct:"c",why:{a:"No.",b:"No.",c:"Correcto: dispositivos que disminuyan atención → 3 puntos.",d:"Sí detraen."}},
{n:120,q:"Según el art.63.5 de la Ley de Seguridad Vial (RDL 6/2015), la superación de cursos de conducción segura y eficiente a los que se hace referencia en el anexo VIII de esta ley, siempre que se cumplan los requisitos establecidos y se tenga saldo positivo:",o:{a:"Compensará con cuatro puntos adicionales hasta un máximo de quince puntos y con una frecuencia máxima de un curso de cada tipo cada dos años.",b:"Compensará con dos puntos adicionales hasta un máximo de quince puntos y con una frecuencia máxima de un curso de cada tipo cada dos años.",c:"Compensará con seis puntos adicionales hasta un máximo de doce puntos y con una frecuencia máxima de un curso de cada tipo por año.",d:"Compensará con tres puntos adicionales hasta un máximo de doce puntos y con una frecuencia máxima de un curso de cada tipo cada dos años."},correct:"b",why:{a:"Son 2 puntos, no 4.",b:"Correcto: +2 puntos, máx 15, frecuencia cada 2 años.",c:"Son 2 puntos y máx 15, no 6 y 12.",d:"No."}},
{n:121,q:"Según se establece en el Anexo VIII de la Ley de Seguridad Vial (RDL 6/2015), respecto a los cursos de conducción segura y eficiente, indique la afirmación incorrecta:",o:{a:"Tendrán como objeto formar a los conductores en distintas técnicas orientadas a evitar accidentes y reducir el consumo de combustible y las emisiones contaminantes, preparando al conductor para solventar situaciones de peligro, adoptando buenas prácticas en la conducción y el equipamiento, y evitando conductas de riesgo.",b:"Se podrán realizar cursos de distintas clases diferenciando entre tipos de vehículos y de entorno: conducción segura y eficiente en carretera o en zona urbana.",c:"Su contenido y requisitos serán los que se establezcan por Orden del Ministerio del Interior, debiendo tener en todo caso una duración mínima de diez horas, que incluya formación teórica y formación práctica y contenidos específicos sobre respeto a los conductores más vulnerables.",d:"Por Orden del Ministerio del Interior se establecerán los mecanismos de certificación y control que garanticen que los cursos se realizan conforme a lo establecido en la misma y en el presente anexo."},correct:"c",why:{a:"Correcto.",b:"Correcto.",c:"La duración mínima establecida legalmente no es de 10 horas o los contenidos específicos citados difieren de los del Anexo VIII real.",d:"Correcto."}},
{n:122,q:"El contenido y los requisitos de los cursos de conducción segura y eficiente serán los que se establezcan por Orden del Ministerio del Interior, que incluya formación teórica y formación práctica y contenidos específicos sobre respeto a los ciclistas y conductores de vehículos de movilidad personal como conductores de vehículos más vulnerables, debiendo tener, en todo caso, una duración:",o:{a:"Mínima de seis horas.",b:"Mínima de diez horas.",c:"Máxima de doce horas.",d:"Máxima de diez horas."},correct:"a",why:{a:"✓ Respuesta oficial. No.",b:"⚠ Mi respuesta inicial (incorrecta): Correcto: duración mínima de 10 horas.",c:"No.",d:"No."}},
{n:123,q:"De conformidad con lo establecido en el art.46 del Reglamento General de Conductores (RD 818/2009), los permisos y licencias de conducción, en función de las aptitudes psicofísicas de los conductores, se clasifican en:",o:{a:"Discrecionales y reglados.",b:"Ordinarios y extraordinarios.",c:"Directos o indirectos.",d:"Normales o especiales."},correct:"b",why:{a:"No.",b:"Correcto: Ordinarios y Extraordinarios (art.46 RGCond).",c:"No.",d:"No."}},
{n:124,q:"De conformidad con lo establecido en el Reglamento General de Conductores (RD 818/2009), una persona que necesita una adaptación en su vehículo porque padece una discapacidad, puede obtener un permiso de conducción:",o:{a:"Ordinario.",b:"Extraordinario.",c:"Normal.",d:"Especial."},correct:"b",why:{a:"No.",b:"Correcto: si precisa adaptaciones en el vehículo → permiso Extraordinario.",c:"No.",d:"No."}},
{n:125,q:"De conformidad con lo establecido en el Reglamento General de Conductores (RD 818/2009), un conductor que tenga necesidad de utilizar lentes correctoras para conducir puede obtener un permiso de conducción:",o:{a:"Ordinario.",b:"Extraordinario.",c:"Normal.",d:"Especial."},correct:"a",why:{a:"Correcto: lentes correctoras → permiso Ordinario con restricción codificada.",b:"Las lentes no requieren adaptaciones en el vehículo.",c:"No.",d:"No."}},
{n:126,q:"De conformidad con lo establecido en el Reglamento General de Conductores (RD 818/2009), un conductor que tenga necesidad de utilizar audífono para adquirir la agudeza auditiva mínima para conducir puede obtener un permiso de conducción:",o:{a:"Ordinario.",b:"Extraordinario.",c:"Normal.",d:"Especial."},correct:"a",why:{a:"Correcto: audífono → permiso Ordinario con restricción codificada.",b:"No precisa adaptación del vehículo.",c:"No.",d:"No."}},
{n:127,q:"Según el Reglamento General de Conductores (RD 818/2009), con respecto al permiso de la clase AM, indique la afirmación incorrecta:",o:{a:"Autoriza a conducir vehículos para personas de movilidad reducida, ciclomotores de dos o tres ruedas y cuatriciclos ligeros.",b:"La edad mínima para obtenerlo será de 15 años cumplidos.",c:"Hasta los dieciséis años no autoriza a transportar pasajeros en el vehículo.",d:"Podrá estar limitado a la conducción de ciclomotores de tres ruedas y cuatriciclos ligeros."},correct:"c",why:{a:"⚠ Mi respuesta inicial (incorrecta): Los vehículos para personas de movilidad reducida no están incluidos en la clase AM; requieren autorización específica.",b:"Correcto: edad mínima 15 años.",c:"✓ Respuesta oficial. Correcto: hasta 16 años sin pasajeros.",d:"Correcto: puede limitarse a 3 ruedas y cuatriciclos ligeros."}},
{n:128,q:"Según el Reglamento General de Conductores (RD 818/2009), con respecto al permiso de conducción de la clase A1, indique la afirmación incorrecta:",o:{a:"Autoriza a conducir vehículos para personas de movilidad reducida y motocicletas con una cilindrada máxima de 125 cm3.",b:"Autoriza a conducir motocicletas con una potencia máxima de 11 kW y una relación potencia/peso máxima de 0,1 KW/Kg.",c:"Autoriza a conducir cuatriciclos de motor con una potencia máxima de 0,10 kW.",d:"Autoriza a conducir triciclos de motor cuya potencia máxima no exceda de 15 kW."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"El límite de potencia para cuatriciclos en clase A1 no es 0,10 kW (sería irrisoriamente bajo). La redacción es errónea.",d:"Cierto."}},
{n:129,q:"Según el Reglamento General de Conductores (RD 818/2009), la edad mínima para obtener el permiso de conducción de la clase A1 es de:",o:{a:"15 años cumplidos.",b:"16 años cumplidos.",c:"17 años cumplidos.",d:"18 años cumplidos."},correct:"b",why:{a:"No.",b:"Correcto: edad mínima clase A1 → 16 años.",c:"No.",d:"No."}},
{n:130,q:"Según el Reglamento General de Conductores (RD 818/2009), con respecto al permiso de conducción de la clase A2, indique la afirmación incorrecta:",o:{a:"La edad mínima para obtenerlo será de 18 años cumplidos.",b:"Hasta los 21 años cumplidos no autorizará para conducir triciclos de motor cuya potencia máxima exceda de 15 kW.",c:"Autoriza para conducir motocicletas con una potencia máxima de 35 kW.",d:"Autoriza para conducir motocicletas con una relación potencia/peso máxima de 0,2 kW/kg y no derivadas de un vehículo con más del doble de su potencia."},correct:"b",why:{a:"Correcto.",b:"Para clase A2 no existe esa restricción específica de triciclos >15 kW hasta 21 años; esa restricción es de clase A.",c:"Correcto.",d:"Correcto."}},
{n:131,q:"Según el Reglamento General de Conductores (RD 818/2009), con respecto al permiso de conducción de la clase A, indique la afirmación incorrecta:",o:{a:"Autoriza a conducir motocicletas y triciclos de motor.",b:"La edad mínima para obtenerlo será de 20 años cumplidos.",c:"Hasta los 21 años cumplidos no autorizará a conducir triciclos de motor cuya potencia máxima exceda de 15 kW.",d:"Para poder obtener este permiso es necesario acreditar una experiencia de 3 años en la conducción de vehículos a los que autoriza el permiso de conducción de la clase A2."},correct:"d",why:{a:"Correcto.",b:"Correcto.",c:"Correcto.",d:"La experiencia exigida en clase A2 para acceder a clase A es de 2 años, no 3."}},
{n:132,q:"Según el Reglamento General de Conductores (RD 818/2009), respecto a los vehículos que autoriza a conducir el permiso de conducción de la clase B, indique cual de los siguientes no es uno de ellos:",o:{a:"Un automóvil con MMA de 3500 Kg.",b:"Un turismo que lleve enganchado un remolque de 600 Kg de peso.",c:"Un cuatriciclo de motor.",d:"Una motocicleta con cilindrada de 450 cm3."},correct:"d",why:{a:"Sí autorizado.",b:"Sí autorizado (remolque ≤750 kg MMA).",c:"Sí autorizado.",d:"Las motocicletas requieren permiso de clase A, no B."}},
{n:133,q:"Según el Reglamento General de Conductores (RD 818/2009), con respecto al permiso de conducción de la clase B, indique la afirmación incorrecta:",o:{a:"La edad mínima para obtenerlo será de 18 años.",b:"Hasta los 21 años no autoriza a llevar pasajeros en el vehículo.",c:"Permite la conducción de Triciclos y Cuatriciclos de Motor, vehículos para personas de movilidad reducida y ciclomotores.",d:"Hasta los 21 años cumplidos no autoriza a conducir triciclos de motor cuya potencia máxima exceda de 15 kW."},correct:"b",why:{a:"Correcto.",b:"El permiso B no establece ninguna restricción sobre el transporte de pasajeros por edad.",c:"Correcto.",d:"Correcto."}},
{n:134,q:"Según el Reglamento General de Conductores (RD 818/2009), con 18 años cumplidos se puede obtener el permiso de la clase B, que autoriza a conducir:",o:{a:"Automóviles cuya MMA no exceda de 3.500 kg que estén diseñados y construidos para el transporte de no más de ocho pasajeros además del conductor. Dichos automóviles podrán llevar enganchado un remolque cuya Mma no exceda de 750 kg.",b:"Conjuntos de vehículos acoplados compuestos por un vehículo tractor de los que autoriza el permiso de clase B y un remolque cuya MMA exceda de 750 kg, siempre que la MMA del conjunto no exceda de 4.250 kg, sin perjuicio de las disposiciones que las normas de aprobación de tipo establezcan para estos vehículos.",c:"Las respuestas a y b son incorrectas.",d:"Las respuestas a y b son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son ciertas.",d:"Correcto: el permiso B autoriza ambas combinaciones."}},
{n:135,q:"Según el Reglamento General de Conductores (RD 818/2009), se podrá conducir, exclusivamente dentro del territorio nacional, con el permiso de la clase B:",o:{a:"Con una antigüedad superior a dos años, automóviles sin remolque impulsados por combustibles alternativos destinados al transporte de mercancías con una MMA superior a 3.500 kg pero que no exceda los 4.250 kg, siempre que la masa que supere los 3.500 kg provenga exclusivamente del exceso de masa del sistema de propulsión, y siempre que no se incremente la capacidad de carga respecto al mismo vehículo.",b:"Con una antigüedad superior a tres años, las motocicletas cuya conducción autoriza el permiso de la clase A1. En el caso de que este permiso se encuentre sometido a adaptaciones, restricciones u otras limitaciones en personas, vehículos o de circulación, para poder conducir estas motocicletas, deberán hacerse constar previamente por la Jefatura Provincial de Tráfico en el permiso las adaptaciones o restricciones que correspondan.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Correcto pero b es incorrecto.",b:"La antigüedad exigida para conducir motocicletas clase A1 con permiso B es de 2 años, no 3.",c:"✓ Respuesta oficial. La b es incorrecta.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: la opción b dice 3 años cuando la norma exige 2 años de antigüedad."}},
{n:136,q:"Según el Reglamento General de Conductores (RD 818/2009), con 18 años cumplidos se puede obtener el permiso de la clase:",o:{a:"A.",b:"B+E",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{a:"El permiso A exige mínimo 20 años (o A2 con 2 años de antigüedad, también 20 años).",b:"✓ Respuesta oficial. B+E se obtiene con B, que sí puede obtenerse a los 18; sin embargo, B+E por sí solo exige el B previo.",c:"La a es incorrecta.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: la a es incorrecta (A requiere 20 años); la b también requiere haber tenido antes el B (no se obtiene solo con 18 sin más)."}},
{n:137,q:"Según el Reglamento General de Conductores (RD 818/2009), respecto al permiso de conducir de la clase B+E, señale la afirmación incorrecta:",o:{a:"Se puede obtener a partir de 18 años cumplidos.",b:"Hasta los 21 años cumplidos no autorizará a conducir triciclos de motor cuya potencia máxima exceda de 15 kW.",c:"Autoriza a conducir conjuntos de vehículos acoplados compuestos por un vehículo tractor de los que autoriza a conducir el permiso de la clase B y un remolque  cuya MMA no exceda de 3.500 kg, sin perjuicio de las disposiciones que las normas de aprobación de tipo establezcan para estos vehículos.",d:"Autoriza a conducir conjuntos de vehículos acoplados compuestos por un vehículo tractor de los que autoriza a conducir el permiso de la clase B y un semirremolque cuya MMA no exceda de 3.500 kg, sin perjuicio de las disposiciones que las normas de aprobación de tipo establezcan para estos vehículos."},correct:"b",why:{a:"Correcto: 18 años.",b:"El permiso B+E no tiene relación con triciclos de motor; esa restricción es del permiso de clase A.",c:"Correcto.",d:"Correcto."}},
{n:138,q:"Según el Reglamento General de Conductores (RD 818/2009), con 18 años cumplidos se pueden obtener el permiso de la clase:",o:{a:"C1.",b:"D1.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"✓ Respuesta oficial. Correcto: C1 se obtiene a los 18.",b:"D1 puede obtenerse a los 18 si se posee el CAP modalidad ordinaria (excepcionalmente).",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: ambas pueden obtenerse con 18 años.",d:"No; las dos son posibles a los 18."}},
{n:139,q:"Según el Reglamento General de Conductores (RD 818/2009), con el permiso de conducción de la clase C1 se pueden conducir:",o:{a:"Automóviles distintos de los que autoriza a conducir el permiso de la clase D1 cuya MMA exceda de 3500Kg y no sobrepase los 9.000 Kg.",b:"Automóviles distintos de los que autoriza a conducir el permiso de la clase D, cuya MMA exceda de 3500 Kg y no sobrepase los 7500 Kg, diseñados y construidos  para el transporte de más 9 y menos de 17 pasajeros, incluido el conductor.",c:"Motocicletas de cualquier cilindrada, potencia o relación potencia/peso.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"d",why:{a:"El límite de C1 es 7.500 kg, no 9.000.",b:"C1 no autoriza vehículos de pasajeros; esos son D1.",c:"Las motocicletas requieren permiso de clase A.",d:"Correcto: ninguna de las opciones describe correctamente lo que autoriza C1."}},
{n:140,q:"Según el Reglamento General de Conductores (RD 818/2009), el permiso de conducir de la clase C1:",o:{a:"Autoriza a conducir automóviles distintos de los que autoriza a conducir el permiso de las clases D1 o D.",b:"Autoriza a conducir automóviles cuya MMA exceda de 3.500 kg y no sobrepase los 7.500 kg, diseñados y construidos para el transporte de no más de ocho pasajeros además del conductor.",c:"Autoriza a conducir determinados automóviles, que podrán llevar enganchado un remolque cuya MMA no exceda de 750 kg.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres son características de C1."}},
{n:141,q:"De conformidad con lo dispuesto en el Reglamento General de Conductores, indique la afirmación incorrecta:",o:{a:"La edad exigida para obtener un permiso de la clase C1+E es de 18 años cumplidos.",b:"Con el permiso de la clase C1 se puede arrastrar un remolque de hasta 1.500 kg. de peso.",c:"La edad exigida para obtener el permiso de la clase A1 es de 16 años cumplidos.",d:"La edad exigida para obtener el permiso de la clase C es de 21 años."},correct:"b",why:{a:"Correcto.",b:"Con el permiso C1 solo se puede arrastrar un remolque de hasta 750 kg, no 1.500 kg.",c:"Correcto.",d:"Correcto."}},
{n:142,q:"Según el Reglamento General de Conductores (RD 818/2009), el permiso de conducción de la clase C1+E autoriza a conducir:",o:{a:"Conjuntos de vehículos acoplados compuestos por un vehículo tractor de los que autoriza a conducir el permiso de la clase B, y un remolque o semirremolque cuya MMA exceda de 3500 kg, siempre que la MMA del conjunto no exceda de 12.000 Kg.",b:"Conjuntos de vehículos acoplados compuestos por un vehículo tractor de los que autoriza a conducir el permiso de la clase C1 y un remolque cuya MMA exceda de 750 kg, siempre que la MMA autorizada del conjunto así formado no exceda de 12.000 kg.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto: B-type tractor + heavy trailer (combinación B+E extend).",b:"Cierto: C1 tractor + remolque >750 kg, conjunto ≤12.000 kg.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:143,q:"Según el Reglamento General de Conductores (RD 818/2009), y con respecto al permiso de conducción de la clase C, indique la afirmación incorrecta:",o:{a:"Este permiso solo puede expedirse a quienes se hallen en posesión de un permiso de la clase B2+E en vigor.",b:"Autoriza a conducir automóviles distintos de los que autoriza a conducir el permiso de las clases D1 o D, cuya masa máxima autorizada exceda de 3.500 kg que estén diseñados y construidos para el transporte de no más de ocho pasajeros además del conductor.",c:"Los automóviles a los que autoriza a conducir este permiso, podrán llevar enganchado un remolque cuya masa máxima autorizada no exceda de 750 kg.",d:"Para quienes hayan obtenido el certificado de aptitud profesional (CAP) realizando la modalidad de cualificación inicial ordinaria, la edad mínima para obtenerlo será de 18 años cumplidos."},correct:"a",why:{a:"No existe la clase «B2+E»; para obtener C se exige el permiso de clase B en vigor.",b:"Correcto.",c:"Correcto.",d:"Correcto."}},
{n:144,q:"Según el Reglamento General de Conductores (RD 818/2009), la edad mínima para obtener el permiso de conducción de la clase C, será de:",o:{a:"21 años cumplidos.",b:"20 años cumplidos.",c:"18 años cumplidos.",d:"18 o 20 años cumplidos, según tengan su titular el certificado de aptitud profesional (CAP) o no."},correct:"b",why:{a:"Sin CAP la edad es 21, no 20.",b:"✓ Respuesta oficial. No.",c:"Con CAP ordinario.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: 18 años con CAP ordinario, 21 sin él (verificar la redacción exacta del RGCond)."}},
{n:145,q:"Según el Reglamento General de Conductores (RD 818/2009), y con respecto al permiso de conducción de la clase C+E, indique la afirmación incorrecta:",o:{a:"Se puede obtener a partir de 21 años cumplidos.",b:"Autoriza a conducir conjuntos de vehículos acoplados compuestos por un vehículo tractor de los que autoriza a conducir el permiso de la clase C y un remolque o semirremolque cuya MMA exceda de 750 kg.",c:"Este permiso solo puede expedirse a quienes se hallen en posesión de un permiso de la clase B en vigor.",d:"Para quienes hayan obtenido el certificado de aptitud profesional (CAP) realizando la modalidad de cualificación inicial ordinaria, la edad mínima será de 18 años cumplidos."},correct:"c",why:{a:"Correcto.",b:"Correcto.",c:"Para obtener C+E se requiere el permiso de clase C en vigor, no solo el B.",d:"Correcto."}},
{n:146,q:"Según el Reglamento General de Conductores (RD 818/2009), el permiso de conducción de la clase D1...",o:{a:"Autoriza a conducir automóviles diseñados y construidos para el transporte de no más de 16 pasajeros, además del conductor, siempre que su longitud máxima no exceda de 12 metros.",b:"Autoriza a conducir automóviles diseñados y construidos para el transporte de no más de 16 pasajeros, además del conductor, siempre que su longitud máxima no exceda de 8 metros.",c:"Autoriza a conducir automóviles diseñados y construidos para el transporte de no más de 16 pasajeros, además del conductor, siempre que su longitud máxima no exceda de 10 metros.",d:"Autoriza a conducir automóviles diseñados y construidos para el transporte de no más de 18 pasajeros, además del conductor, siempre que su longitud máxima no exceda de 10 metros."},correct:"b",why:{a:"Longitud máxima incorrecta (12 m).",b:"Correcto: D1 → ≤16 pasajeros + conductor, longitud ≤8 m.",c:"Longitud máxima incorrecta (10 m).",d:"Número de pasajeros incorrecto (18)."}},
{n:147,q:"Con respecto al permiso de conducción de la clase D1, según el Reglamento General de Conductores (RD 818/2009):",o:{a:"Se puede obtener a partir de 21 años cumplidos.",b:"Los automóviles a los que autoriza a conducir este permiso, podrán llevar enganchado un remolque cuya masa máxima autorizada no exceda de 750 kg.",c:"Para quienes hayan obtenido el certificado de aptitud profesional (CAP) realizando la modalidad de cualificación inicial ordinaria, la edad mínima será de 18 años cumplidos, pero solo podrán conducir estos vehículos dentro de territorio nacional hasta que su titular cumpla los 21 años de edad.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres son correctas."}},
{n:148,q:"Con respecto al permiso de conducción de la clase D1+E, según el Reglamento General de Conductores (RD 818/2009):",o:{a:"Se puede obtener a partir de 21 años cumplidos y autoriza a conducir conjuntos de vehículos acoplados compuestos por un vehículo tractor de los que autoriza a conducir el permiso de la clase D1 y un remolque cuya masa máxima autorizada exceda de 750 kg,",b:"Para quienes hayan obtenido el certificado de aptitud profesional (CAP) realizando la modalidad de cualificación inicial ordinaria, la edad mínima será de 18 años cumplidos, pero solo podrán conducir estos vehículos dentro de territorio nacional hasta que su titular cumpla los 21 años de edad.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:149,q:"Según el Reglamento General de Conductores (RD 818/2009), en relación con el permiso de conducción de la clase D, indique la afirmación incorrecta.",o:{a:"Autoriza a conducir automóviles diseñados y construidos para el transporte de más de 8 pasajeros, además del conductor, que podrán llevar enganchado un remolque cuya MMA no exceda de 750 kg.",b:"Este permiso solo puede expedirse a quienes se hallen en posesión de un permiso de la clase B+E en vigor.",c:"La edad mínima para obtenerlo es de 24 años cumplidos.",d:"La edad mínima para su obtención puede ser rebajada cuando se cumplen determinados requisitos."},correct:"b",why:{a:"Correcto.",b:"Para obtener D se exige el permiso de clase B en vigor, no necesariamente B+E.",c:"Correcto (sin CAP).",d:"Correcto."}},
{n:150,q:"Respecto a la obtención del permiso de conducción de la clase D, el Reglamento General de Conductores (RD 818/2009) dispone que, excepcionalmente:",o:{a:"La edad mínima será de 21 años cumplidos para los titulares del certificado de aptitud profesional (CAP) que lo hayan obtenido realizando la modalidad de cualificación inicial ordinaria.",b:"La edad mínima será de 21 años cumplidos si lo han obtenido realizando la modalidad de cualificación inicial acelerada y se trata de transporte de viajeros en servicios regulares cuyo trayecto no supere los 50 km.",c:"La edad mínima será de 23 años cumplidos si lo han obtenido realizando la modalidad de cualificación inicial acelerada.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres describen reducciones excepcionales de la edad para el permiso D."}},
{n:151,q:"Dentro del territorio nacional y hasta que el titular del permiso de la clase D tenga 21 años cumplidos, se podrá conducir, de forma excepcional:",o:{a:"A los 18 años cumplidos en caso de que se conduzcan los vehículos sin pasajeros o si se trata de transporte de viajeros en servicios regulares cuyo trayecto no supere los 50 km, para los titulares del certificado de aptitud profesional (CAP) que lo hayan obtenido realizando la modalidad de cualificación inicial ordinaria.",b:"A los 20 años cumplidos para los titulares del certificado de aptitud profesional (CAP) que lo hayan obtenido realizando la modalidad de cualificación inicial ordinaria.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas excepciones.",d:"Las dos son ciertas."}},
{n:152,q:"Según el Reglamento General de Conductores (RD 818/2009), en relación con el permiso de conducción de la clase D+E, indique la afirmación incorrecta.",o:{a:"Autoriza a conducir conjuntos de vehículos acoplados compuestos por un vehículo tractor de los que autoriza a conducir el permiso de la clase D y un remolque cuya masa máxima autorizada exceda de 750 kg.",b:"Este permiso solo puede expedirse a quienes se hallen en posesión de un permiso de la clase B+E en vigor.",c:"La edad mínima para obtenerlo es de 24 años cumplidos.",d:"La edad mínima para su obtención puede ser rebajada cuando se cumplen determinados requisitos."},correct:"b",why:{a:"Correcto.",b:"Para obtener D+E se requiere el permiso de clase D en vigor, no el B+E.",c:"Correcto.",d:"Correcto."}},
{n:153,q:"Respecto a la obtención del permiso de conducción de la clase D+E, el Reglamento General de Conductores (RD 818/2009) dispone que, excepcionalmente:",o:{a:"La edad mínima será de 21 años cumplidos para los titulares del certificado de aptitud profesional (CAP) que lo hayan obtenido realizando la modalidad de cualificación inicial ordinaria.",b:"La edad mínima será de 21 años cumplidos si lo han obtenido realizando la modalidad de cualificación inicial acelerada y se trata de transporte de viajeros en servicios regulares cuyo trayecto no supere los 50 km.",c:"La edad mínima será de 23 años cumplidos si lo han obtenido realizando la modalidad de cualificación inicial acelerada.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres."}},
{n:154,q:"Dentro del territorio nacional y hasta que el titular del permiso de la clase D+E tenga 21 años cumplidos, se podrá conducir, de forma excepcional:",o:{a:"A los 18 años cumplidos en caso de que se conduzcan los vehículos sin pasajeros o si se trata de transporte de viajeros en servicios regulares cuyo trayecto no supere los 50 km, para los titulares del certificado de aptitud profesional (CAP) que lo hayan obtenido realizando la modalidad de cualificación inicial ordinaria.",b:"A los 20 años cumplidos para los titulares del certificado de aptitud profesional (CAP) que lo hayan obtenido realizando la modalidad de cualificación inicial ordinaria»",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:155,q:"Para la conducción profesional de los vehículos que autoriza a conducir el permiso de las clases C1, C1+E, C, C +E, D1, D1 +E, D o D+E, además de los requisitos exigidos en el art.5 del Reglamento General de Conductores, deberán cumplirse:",o:{a:"Los establecidos en el Real Decreto 1032/2007.",b:"Los establecidos en el Real Decreto 284/2021.",c:"Los establecidos en el Real Decreto 132/2023.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{a:"Cierto.",b:"✓ Respuesta oficial. Cierto.",c:"Cierto.",d:"⚠ Mi respuesta inicial (incorrecta): Las tres normas son aplicables al CAP (Certificado de Aptitud Profesional)."}},
{n:156,q:"Conforme a lo dispuesto en el Reglamento General de Conductores (RD 818/2009), indique la afirmación incorrecta:",o:{a:"El permiso de la clase A solo puede expedirse a conductores que ya sean titulares de un permiso en vigor de la clase A2 con, al menos, dos años de antigüedad, y que  superen la formación establecida en la Orden INT/2323/2011.",b:"Los permisos de las clases C1 y C solo pueden expedirse a conductores que ya sean titulares de un permiso en vigor de la clase B.",c:"El permiso de la clase D solo puede expedirse a conductores que ya sean titulares de un permiso en vigor de la clase B con, al menos, dos años de antigüedad.",d:"Los permisos de las clases D1 y D solo pueden expedirse a conductores que ya sean titulares de un permiso en vigor de la clase B."},correct:"c",why:{a:"Correcto.",b:"Correcto.",c:"Para obtener D solo se requiere el permiso de clase B en vigor, sin exigir años mínimos de antigüedad.",d:"Correcto."}},
{n:157,q:"El Reglamento General de Conductores (RD 818/2009) establece que:",o:{a:"La obtención del permiso de conducción de la clase C+E implica la concesión del de la clase C1+E.",b:"La obtención del permiso de conducción de la clase C+E implica la concesión del de la clase D+E cuando su titular posea el de la clase D.",c:"La obtención del permiso de conducción de la clase C, implica la concesión del de la clase C1 y la obtención del de la clase D, la concesión del de la clase D1.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres."}},
{n:158,q:"El Reglamento General de Conductores (RD 818/2009) establece:",o:{a:"Que la obtención del permiso de la clase D+E implica la concesión del permiso D1+E.",b:"Que la obtención del permiso de la clase C1+E implica la concesión del permiso A+E.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"✓ Respuesta oficial. La a es correcta (D+E implica D1+E).",b:"C1+E no tiene relación con A+E (A es para motocicletas).",c:"La b es falsa.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: la b es incorrecta, por lo que no pueden ser ambas correctas."}},
{n:159,q:"El Reglamento General de Conductores (RD 818/2009) establece que:",o:{a:"La obtención del permiso de conducción de la clase A1 implica la concesión del de la clase AM.",b:"La obtención del permiso de conducción de las clases C1+E, C+E, D1+E y D+E implica la concesión del de la clase B+E.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto: A1 incluye AM.",b:"Cierto: cualquier +E de clase superior implica B+E.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:160,q:"El Reglamento General de Conductores (RD 818/2009) establece que el permiso de la clase A2:",o:{a:"Puede obtenerse superando las pruebas de control de conocimientos y de control de aptitudes y comportamientos previstas en los artículos 47 a 49 de este Reglamento.",b:"Puede obtenerse superando únicamente la prueba de control de aptitudes y comportamientos del artículo 49.2 de este Reglamento, cuando se es titular de un permiso de conducción de la clase A1 con una experiencia mínima de 2 años en la conducción de las motocicletas que autoriza a conducir dicho permiso.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto: vía directa (pruebas teórica + práctica).",b:"Cierto: vía acceso desde A1 con 2 años experiencia (solo prueba práctica).",c:"Correcto: ambas vías.",d:"Las dos son ciertas."}},
{n:161,q:"El Reglamento General de Conductores (RD 818/2009) establece que:",o:{a:"Quienes estén en posesión del permiso de la clase B en vigor, con una antigüedad superior a dos años, podrán conducir dentro del territorio nacional las motocicletas cuya conducción autoriza el permiso de la clase A1.",b:"Para conducir vehículos especiales agrícolas autopropulsados, o sus conjuntos, cuya masa o dimensiones máximas autorizadas no excedan de los límites establecidos para los vehículos ordinarios, se requerirá permiso de la clase B, o licencia de conducción LVA.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{a:"Cierto: B con >2 años permite conducir motocicletas clase A1 en territorio nacional.",b:"✓ Respuesta oficial. Cierto: se requiere B o LVA para vehículos agrícolas dentro de los límites ordinarios.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: ambas.",d:"Las dos son ciertas."}},
{n:162,q:"Según el Reglamento General de Conductores (RD 818/2009), con el permiso de la clase B se puede conducir:",o:{a:"Una motocicleta, cualquiera que sea su potencia.",b:"Un vehículo especial no agrícola cuya velocidad máxima no exceda de 40 Km/hora y su MMA no exceda de 3.500 kg., ya que si excede de cualquiera de estos límites, se requerirá el permiso de conducción que corresponda a su masa MMA.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Con B solo se pueden conducir motocicletas de clase A1 con >2 años de antigüedad en territorio nacional, no cualquier motocicleta.",b:"La condición adicional de que si excede en MMA se requiere otro permiso no está formulada correctamente.",c:"✓ Respuesta oficial. La a es incorrecta.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: la opción a es incorrecta (no autoriza cualquier motocicleta)."}},
{n:163,q:"El Reglamento General de Conductores (RD 818/2009) establece que:",o:{a:"Que los vehículos para personas con movilidad reducida se pueden conducir con el permiso de la clase AM y A1.",b:"Que los vehículos para personas con movilidad reducida se pueden conducir con el permiso de la clase B.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: AM, A1 y B autorizan vehículos para personas con movilidad reducida.",d:"Las dos son ciertas."}},
{n:164,q:"Conforme a lo dispuesto en el Reglamento General de Conductores (RD 818/2009), indique la afirmación incorrecta:",o:{a:"Los permisos de las clases B+E, C1+E, C+E, D1+E y D+E solo podrán expedirse a conductores que ya sean titulares de un permiso en vigor de las clases B, C1, C, D1 o D, respectivamente.",b:"Los permisos de las clases B, B+E, C1, C1+E, C, C+E, D1, D1+E, D y D+E autorizan a conducir motocicletas con o sin sidecar.",c:"Para conducir un conjunto formado por un vehículo tractor de la categoría B y un remolque cuya masa máxima autorizada sea superior a 750 kg, en el caso de que el conjunto así formado exceda de 3.500 kg, será necesario superar la prueba de aptitudes y comportamientos que se indica en los artículos 48.2 y 49.2. de dicho Reglamento.",d:"La obtención del permiso de conducción de la clase A2 implica la concesión del de la clase A1."},correct:"b",why:{a:"Correcto.",b:"Ninguno de esos permisos autoriza motocicletas; esas requieren clase A.",c:"Correcto.",d:"Correcto."}},
{n:165,q:"Conforme a lo dispuesto en el Reglamento General de Conductores (RD 818/2009), indique la afirmación incorrecta:",o:{a:"Los permisos de las clases B, B+E, C1, C1+E, C, C+E, D1, D1+E, D y D+E no autorizan a conducir motocicletas con o sin sidecar.",b:"La obtención del permiso de conducción de la clase C implica la concesión del de las clases C1, C+E y B+E.",c:"Para conducir vehículos especiales no agrícolas, o sus conjuntos, que transporten personas se requerirá permiso de la clase B cuando el número de personas transportadas, incluido el conductor, no exceda de nueve y de la clase D1 cuando exceda de nueve y no exceda de diecisiete.",d:"Para conducir vehículos especiales no agrícolas, o sus conjuntos, que transporten personas se requerirá permiso de la clase D cuando el número de personas transportadas, incluido el conductor, exceda de diecisiete."},correct:"b",why:{a:"Correcto.",b:"La obtención de C implica C1 y B+E, pero no implica C+E (que requiere licencia separada para el remolque «E»).",c:"Correcto.",d:"Correcto."}},
{n:166,q:"El Reglamento General de Conductores (RD 818/2009) establece que:",o:{a:"Para conducir trolebuses se requerirá el permiso exigido para la conducción de autobuses.",b:"Para conducir vehículos especiales agrícolas autopropulsados que tengan una masa o unas dimensiones máximas autorizadas superiores a las establecidas para vehículos ordinarios, o cuya velocidad exceda de 45 Km/hora, se requiere, al menos, el permiso de la clase C1.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"✓ Respuesta oficial. Cierto.",b:"Cierto.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: ambas.",d:"Las dos son ciertas."}},
{n:167,q:"El art.6 del Reglamento General de Conductores (RD 818/2009) establece:",o:{a:"Tres clases de licencia de conducción.",b:"Dos clases de licencia de conducción.",c:"Cuatro clases de licencia de conducción.",d:"Una sola clase de licencia de conducción."},correct:"b",why:{a:"No.",b:"Correcto: el art.6 RGCond establece dos licencias: LCM (movilidad reducida) y LVA (vehículos agrícolas).",c:"No.",d:"No."}},
{n:168,q:"Según el Reglamento General de Conductores (RD 818/2009), y con respecto a la licencia para conducir vehículos para personas con movilidad reducida (LCM), indique la afirmación correcta:",o:{a:"Puede obtenerse a partir de los dieciséis años cumplidos.",b:"Hasta los 18 años no autoriza a transportar pasajeros.",c:"La edad mínima para obtenerla será de 14 años cumplidos.",d:"Hasta los 21 años no autoriza a transportar pasajeros."},correct:"c",why:{a:"La edad mínima es 14, no 16.",b:"La restricción de pasajeros es hasta los 16 años, no 18.",c:"Correcto: LCM desde los 14 años cumplidos.",d:"La restricción es hasta los 16, no 21."}},
{n:169,q:"El Reglamento General de Conductores (RD 818/2009) establece que:",o:{a:"La edad mínima para obtener la licencia para conducir vehículos especiales agrícolas autopropulsados y sus conjuntos (LVA) será de 16 años.",b:"La licencia para conducir vehículos para personas con movilidad reducida puede obtenerse con catorce años cumplidos, pero hasta que su titular cumpla los dieciséis años no le autoriza a transportar pasajeros en el vehículo.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto: LVA desde 16 años.",b:"Cierto: LCM desde 14 años, sin pasajeros hasta 16 años.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:170,q:"Respecto a la licencia para conducir vehículos para personas con movilidad reducida, el Reglamento General de Conductores (RD 818/2009) establece que:",o:{a:"Esta licencia no se exigirá a quien ya sea titular de un permiso de conducción de las clases A1 o B en vigor.",b:"Esta licencia dejará de ser válida si su titular obtiene con posterioridad permiso de conducción de las clases A1 o B.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:171,q:"Según el Reglamento General de Conductores (RD 818/2009), y con respecto a la licencia para conducir vehículos especiales agrícolas autopropulsados y sus conjuntos (LVA), indique la afirmación incorrecta:",o:{a:"Autoriza a conducir vehículos especiales agrícolas autopropulsados y sus conjuntos, cuya masa o dimensiones máximas autorizadas no excedan de los límites establecidos para vehículos ordinarios o cuya velocidad máxima no exceda de 45 km/hora.",b:"Esta licencia no se exigirá a quien ya sea titular de un permiso de conducción de la clase A1 en vigor. Si su titular obtiene con posterioridad un permiso de esta clase, la licencia dejará de ser válida.",c:"La edad mínima para obtenerla será de 16 años.",d:"Esta licencia no se exigirá a quien ya sea titular de un permiso de conducción de la clase B en vigor. Si su titular obtiene con posterioridad un permiso de esta clase, la licencia dejará de ser válida."},correct:"b",why:{a:"Correcto.",b:"La LVA no se exige a quien posea permiso B, no A1; la clase A1 (motocicletas) no exime de la LVA.",c:"Correcto.",d:"Correcto."}},
{n:172,q:"Para conducir vehículos que transporten mercancías peligrosas, cuando así lo requieran las disposiciones del ADR, se exigirá una autorización administrativa especial que habilite para ello y, para cuya obtención, su titular:",o:{a:"Debe estar en posesión del permiso de conducción ordinario en vigor requerido para el vehículo de que se trate, al menos con un año de antigüedad.",b:"Debe haber realizado con aprovechamiento un curso de formación inicial básico, autorizado por la Dirección General de Tráfico.",c:"Debe ser declarado apto por la Jefatura Provincial de Tráfico correspondiente.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Los tres requisitos son exigibles."}},
{n:173,q:"Según el Reglamento General de Conductores (RD 818/2009), y con respecto a la conducción de vehículos que transportan mercancías peligrosas, indique la afirmación incorrecta:",o:{a:"La autorización especial requerida para conducir dichos vehículos, por sí sola no autoriza a conducir si no va acompañada del permiso de conducción ordinario en vigor requerido para el vehículo de que se trate.",b:"Para obtener la autorización especial requerida para conducir dichos vehículos, su titular debe estar en posesión del permiso de conducción ordinario, al menos con dos años de antigüedad.",c:"La autorización especial requerida para conducir dichos vehículos deberá llevarla consigo su titular, en unión del correspondiente permiso de conducción.",d:"La autorización especial requerida para conducir dichos vehículos deberá exhibirla su titular ante la autoridad o sus agentes cuando lo soliciten."},correct:"b",why:{a:"Correcto.",b:"La antigüedad exigida es de 1 año, no 2.",c:"Correcto.",d:"Correcto."}},
{n:174,q:"De acuerdo con lo establecido en el Reglamento General de Conductores (RD 818/2009), y con relación a la autorización especial para conducir vehículos que transporten mercancías peligrosas, indique la afirmación incorrecta:",o:{a:"Para obtenerla es preciso estar en posesión del permiso de conducción ordinario en vigor requerido para el vehículo de que se trate, al menos con un año de antigüedad.",b:"Esta autorización, por sí sola, no autoriza a conducir. Debe ir acompañada del permiso de conducción en vigor, correspondiente al vehículo que se trate.",c:"Para obtenerla hay que tener residencia normal en España o en cualquier otro pais de la UE.",d:"La autorización especial se expedirá conforme al modelo que se recoge en el anexo II de este Reglamento."},correct:"c",why:{a:"Correcto.",b:"Correcto.",c:"Se requiere residencia normal en España, no vale cualquier país de la UE.",d:"Correcto."}},
{n:175,q:"Para conducir vehículos que transporten mercancías peligrosas, cuando así lo requieran las disposiciones del ADR, se exigirá una autorización administrativa especial que habilite para ello y, para cuya obtención, su titular:",o:{a:"No debe estar privado del derecho a conducir vehículos por resolución judicial firme.",b:"Debe reunir las aptitudes físicas requeridas.",c:"Debe tener residencia normal en España.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Los tres son requisitos."}},
{n:176,q:"Para conducir vehículos que transporten mercancías peligrosas, cuando así lo requieran las disposiciones del ADR, se exigirá una autorización administrativa especial que habilite para ello, cuya vigencia será de:",o:{a:"Cinco años, pudiendo ser prorrogada por nuevos periodos de igual duración.",b:"Tres años, pudiendo ser prorrogada por nuevos periodos de igual duración.",c:"Dos años, pudiendo ser prorrogada por nuevos periodos de igual duración.",d:"Un año, pudiendo ser prorrogada por nuevos periodos de igual duración."},correct:"a",why:{a:"Correcto: la autorización ADR tiene vigencia de 5 años prorrogables.",b:"No.",c:"No.",d:"No."}},
{n:177,q:"Según el art.7 del Reglamento General de Conductores (RD 818/2009), para obtener un permiso o una licencia de conducción se requerirá:",o:{a:"En el caso de extranjeros, acreditar la situación de residencia normal o estancia por estudios en España de, al menos, seis meses y haber cumplido la edad requerida.",b:"No estar privado por resolución judicial del derecho a conducir vehículos de motor y ciclomotores, ni hallarse sometido a una suspensión o intervención administrativa del permiso o licencia de conducción que se posea.",c:"Que haya transcurrido el plazo legalmente establecido, una vez declarada la pérdida de vigencia del permiso o licencia de conducción del que fuera titular como consecuencia de la pérdida total de los puntos asignados.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Los tres son requisitos del art.7 RGCond."}},
{n:178,q:"Según el art.7 del Reglamento General de Conductores (RD 818/2009), para obtener un permiso o una licencia de conducción se requerirá:",o:{a:"Reunir las aptitudes psicofísicas requeridas en relación con la clase del permiso o licencia de conducción que se solicite.",b:"Ser declarado apto por la Jefatura Provincial de Tráfico en las pruebas teóricas y prácticas que, en relación con cada clase de permiso o licencia de conducción, se determinan en el título II.",c:"No ser titular de un permiso de conducción expedido en otro Estado miembro de la Unión Europea o en otro Estado parte del Acuerdo sobre el Espacio Económico Europeo, ni haber sido restringido, suspendido o anulado en otro Estado miembro el permiso de conducción que poseyese.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Los tres son requisitos."}},
{n:179,q:"Según el Reglamento General de Conductores (RD 818/2009), los que padezcan enfermedad o deficiencia orgánica o funcional que les incapacite para obtener un permiso o licencia de conducción ordinario:",o:{a:"Deberán aportar una certificación emitida por facultativo colegiado que determine las enfermedades o deficiencias y las medidas correctoras que pueden adoptarse.",b:"Podrán obtener un permiso o licencia de conducción extraordinarios sujetos a las restricciones que en cada caso procedan.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:180,q:"Según el Reglamento General de Conductores (RD 818/2009), cualquier variación de los datos que figuran en el permiso o licencia de conducción, o del domicilio de su titular, deberá ser comunicada a la Jefatura Provincial de Tráfico, en el plazo de:",o:{a:"30 días, contados desde la fecha en que se produzca.",b:"15 días, contados desde la fecha en que se produzca.",c:"10 días, contados desde el día siguiente de la fecha en que se produzca.",d:"5 días, contados desde el día siguiente de la fecha en que se produzca."},correct:"b",why:{a:"No.",b:"Correcto: 15 días desde que se produzca el cambio.",c:"No.",d:"No."}},
{n:181,q:"Según el art.11 del Reglamento General de Conductores (RD 818/2009), la posesión de un permiso de conducción original y de un duplicado del mismo:",o:{a:"Será denunciada conforme a lo previsto en la Ley sobre Tráfico, Circulación de Vehículos a motor y Seguridad Vial.",b:"Dará lugar a la inmovilización del vehículo hasta que se determinen las posibles responsabilidades del conductor.",c:"Determinará la denuncia de dicha infracción conforme a lo previsto en la vigente Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial, y, además, se procederá a la recogida inmediata del permiso duplicado para su remisión a la Jefatura Provincial de Tráfico correspondiente.",d:"Dará lugar a la recogida inmediata del permiso original para su remisión a la Jefatura Provincial de Tráfico que, de resultar falsa la causa alegada para obtener el duplicado, dará cuenta del hecho a la autoridad judicial por si existiere responsabilidad penal."},correct:"d",why:{a:"Parcial.",b:"No procede la inmovilización.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: denuncia + recogida del duplicado + remisión a la JPT.",d:"✓ Respuesta oficial. Se recoge el duplicado, no el original."}},
{n:182,q:"Según el art.11 del Reglamento General de Conductores (RD 818/2009), respecto a la vigencia del permiso y de la licencia de conducción, indique la afirmación incorrecta:",o:{a:"El permiso de conducción de las clases C1, C1 + E, C, C + E, D1, D1 + E, D y D + E tendrá un período de vigencia de cinco años mientras su titular no cumpla los sesenta y cinco años y de tres años a partir de esa edad.",b:"El permiso de conducción de las clases AM, A1, A2, A, B y B+E y la licencia de conducción, cualquiera que sea su clase, tendrán un período de vigencia de diez años mientras su titular no cumpla los sesenta y cinco años y de cinco años a partir de esa edad.",c:"La solicitud de prórroga de vigencia del permiso o licencia podrá presentarse con una antelación máxima de dos meses a su fecha de caducidad, computándose desde esta última fecha el nuevo período de vigencia de la autorización.",d:"La vigencia de los permisos y las licencias de conducción estará subordinada a que su titular mantenga los requisitos exigidos para su otorgamiento."},correct:"c",why:{a:"Correcto.",b:"Correcto.",c:"La antelación máxima para solicitar prórroga es de tres meses, no dos.",d:"Correcto."}},
{n:183,q:"Según el art.11 del Reglamento General de Conductores (RD 818/2009), y con respecto a la vigencia del permiso y de la licencia de conducción, indique la afirmación incorrecta:",o:{a:"La solicitud de prórroga de vigencia del permiso o licencia podrá presentarse con una antelación máxima de dos meses a su fecha de caducidad, computándose desde esta última fecha el nuevo período de vigencia de la autorización.",b:"El período de vigencia de las diversas clases de permiso y licencia de conducción vigentes podrá reducirse si, al tiempo de su concesión o de la prórroga de su vigencia, se comprueba que su titular padece enfermedad o deficiencia que, si bien de momento no impide aquélla, es susceptible de agravarse.",c:"El permiso o licencia de conducción cuya vigencia hubiese vencido no autoriza a su titular a conducir y su utilización dará lugar a su intervención inmediata por la autoridad o sus agentes, que lo remitirán a la Jefatura Provincial de Tráfico correspondiente.",d:"La vigencia del permiso y de la licencia de conducción, estará condicionada a que su titular no haya perdido totalmente la asignación inicial de puntos."},correct:"a",why:{a:"La antelación máxima para prórroga es tres meses, no dos.",b:"Correcto.",c:"Correcto.",d:"Correcto."}},
{n:184,q:"El Reglamento General de Conductores (RD 818/2009) establece que:",o:{a:"La vigencia de la licencia de conducción que autoriza para conducir vehículos para personas con movilidad reducida será de 10 años mientras su titular no cumpla los 65 años de edad.",b:"El permiso de la clase D1 tendrá una vigencia de 5 años a partir de que su titular cumpla los 65 años de edad.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"✓ Respuesta oficial. Cierto.",b:"El permiso D1 a partir de los 65 años tiene vigencia de 3 años, no 5.",c:"La b es incorrecta.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: la b es errónea (D1 → 3 años tras los 65, no 5)."}},
{n:185,q:"El Reglamento General de Conductores (RD 818/2009) establece:",o:{a:"Que el permiso de la clase AM tendrá una vigencia de 5 años a partir de que su titular cumpla los 65 años de edad.",b:"Que el permiso de la clase B tendrá una vigencia de 10 años mientras su titular no cumpla los 65 años de edad.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto: AM → 5 años desde los 65.",b:"Cierto: B → 10 años hasta los 65.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:186,q:"El Reglamento General de Conductores (RD 818/2009) establece:",o:{a:"Que el permiso de la clase D+E tendrá una vigencia de 5 años mientras su titular no cumpla los 65 años de edad.",b:"Que el permiso de la clase A tendrá una vigencia de 5 años mientras su titular no cumpla los 65 años de edad.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"✓ Respuesta oficial. Cierto: D+E → 5 años hasta los 65.",b:"El permiso A tiene vigencia de 10 años hasta los 65 años, no 5.",c:"La b es incorrecta.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: la b dice 5 años cuando son 10."}},
{n:187,q:"El Reglamento General de Conductores (RD 818/2009) establece:",o:{a:"Que la vigencia de un permiso o licencia de conducción estará condicionada a que su titular no haya perdido totalmente la asignación inicial de puntos.",b:"Que la vigencia de los permisos y licencias de conducción estará subordinada a que su titular mantenga los requisitos exigidos para su otorgamiento.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas condiciones.",d:"Las dos son ciertas."}},
{n:188,q:"Si usted descubre que el conductor de un determinado vehículo está conduciendo con el permiso de conducción caducado, su actuación como funcionario de la Policía Local será:",o:{a:"Inmovilizar el vehículo hasta que el conductor obtenga una prórroga de la vigencia de su permiso de conducción.",b:"Intervenir inmediatamente dicho permiso caducado y remitirlo a la Jefatura Provincial de Tráfico correspondiente.",c:"Las respuestas a y b son correctas.",d:"Las respuesta a y b son incorrectas."},correct:"b",why:{a:"Cierto: inmovilización.",b:"✓ Respuesta oficial. Cierto: intervención del permiso caducado.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: ambas.",d:"Las dos son ciertas."}},
{n:189,q:"El titular de un permiso o licencia de conducción caducados podrá solicitar su prórroga y, según el art.13 del Reglamento General de Conductores (RD 818/2009):",o:{a:"Podrá presentarse con una antelación máxima de tres meses a su fecha de caducidad, computándose desde esta última fecha el nuevo período de vigencia de la autorización.",b:"En supuestos excepcionales debidamente justificados, se podrá solicitar con una antelación superior a tres meses, computándose el nuevo período de vigencia desde la fecha en que se haya presentado la solicitud.",c:"A la solicitud de modelo oficial, que deberá estar suscrita por el interesado, se acompañarán los documentos que se indican en el anexo III apartado B de este Reglamento..",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres."}},
{n:190,q:"La solicitud de prórroga de un permiso o licencia de conducción podrá presentarse con una antelación máxima de.",o:{a:"Un mes, a su fecha de caducidad.",b:"Dos meses, a su fecha de caducidad.",c:"Tres meses, a su fecha de caducidad.",d:"Seis meses, a su fecha de caducidad."},correct:"c",why:{a:"No.",b:"No.",c:"Correcto: tres meses de antelación máxima.",d:"No."}},
{n:191,q:"De conformidad con lo previsto en el Reglamento General de Conductores (RD 818/2009), son válidos para conducir en España:",o:{a:"Los permisos de conducción expedidos por cualquier Estado miembro de la Unión Europea.",b:"Los permisos de conducción expedidos por cualquier Estado que sea parte del Acuerdo sobre el Espacio Económico Europeo.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: UE y EEE.",d:"Las dos son ciertas."}},
{n:192,q:"Según lo establecido en las Disposiciones del Reglamento General de Conductores (RD 818/2009):",o:{a:"Las licencias de conducción de ciclomotores, expedidas con anterioridad a la entrada en vigor del Real Decreto 772/1997, que no estaban sujetas a período de vigencia alguno pasan a ser equiparadas a las actuales y por consiguiente pierden su vigencia en los plazos previstos en el artículo 12.2 del R.D. 818/2009 (D.A. 1ª).",b:"Quienes se hallen en posesión de un permiso de las clases A1 o A2 o de una licencia de conducción de ciclomotores, obtenidos antes de la entrada en vigor del R.D 772/1997, están autorizados a conducir motocultores y tractores agrícolas y máquinas agrícolas automotrices cuya MMA no exceda de 1000 kg y cuya velocidad máxima autorizada no exceda de 20 Km/hora, siempre que no lleven remolque. (D.T 3ª).",c:"Quienes a la entrada en vigor del Reglamento fueran titulares de un permiso de conducción de la clase B1 (TA) restringido para la conducción de tractores y máquinas automotrices agrícolas, están autorizados a conducir vehículos especiales agrícolas autopropulsados y conjuntos de los mismos, aunque su masa o dimensiones máximas excedan de los límites establecidos para los vehículos ordinarios. (D.T. 4ª).",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres son disposiciones del RGCond."}},
{n:193,q:"En cuanto al permiso de conducción expedido por uno de los Estados miembros de la UE o por un Estado que sea parte del Acuerdo sobre el Espacio Económico Europeo, cuyo titular haya adquirido residencia normal en España, el Reglamento General de conductores establece que:",o:{a:"Su titular quedará sometido a las disposiciones españolas en cuanto a su período de vigencia, control de aptitudes psicofísicas y asignación de un crédito de puntos.",b:"Su titular puede solicitar el canje de su permiso de conducción por otro español equivalente.",c:"Las Jefaturas Provinciales de Tráfico procederán al canje de oficio cuando el titular de uno de estos permisos haya sido sancionado por la comisión de infracciones que conlleven la pérdida de puntos, con el fin de poder aplicarle la normativa española.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres."}},
{n:194,q:"Respecto a los permisos de conducción expedidos en terceros países, el art.21 del Reglamento General de Conductores (RD 818/2009) dispone los que son válidos para conducir en España, no encontrándose entre ellos:",o:{a:"Los nacionales de otros países que estén expedidos de conformidad con el anexo 9 del Convenio Internacional de Ginebra de 19 de septiembre de 1949 o con el anexo 6 del Convenio Internacional de Viena de 1968.",b:"Los internacionales expedidos en el extranjero de conformidad con el modelo del anexo 10 del Convenio Internacional de Ginebra, de 19 de septiembre de 1949.",c:"Los nacionales de otros países que estén expedidos de conformidad con el anexo C de la Convención Internacional de París de 1926.",d:"Los nacionales de otros países que estén redactados en castellano o vayan acompañados de una traducción oficial del mismo."},correct:"c",why:{a:"Cierto: permisos nacionales de Ginebra 1949 o Viena 1968 sí son válidos.",b:"Cierto: permisos internacionales de Ginebra 1949 sí son válidos.",c:"✓ Respuesta oficial. Cierto: Convención de París 1926 también válida.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: estar redactado en castellano o con traducción no es criterio de validez; es la fuente convencional lo que importa."}},
{n:195,q:"Respecto a los permisos de conducción expedidos en terceros países, el art.21 del Reglamento General de Conductores (RD 818/2009) dispone los que son válidos para conducir en España, no encontrándose entre ellos:",o:{a:"Los internacionales expedidos en España de conformidad con el modelo del Anexo 10 del Convenio Internacional de Ginebra de 1949.",b:"Los internacionales expedidos en el extranjero de conformidad con los modelos de anexo E de la Convención Internacional de París de 1926.",c:"Los internacionales expedidos en el extranjero de conformidad con los modelos del anexo 7 del Convenio Internacional de Viena de 1968.",d:"Los reconocidos en particulares convenios internacionales multilaterales y bilaterales en los que España sea parte y en las condiciones que en ellos se indiquen."},correct:"a",why:{a:"Correcto: los permisos internacionales expedidos en España (por el Estado español) no son válidos para conducir en España; son para usar en el extranjero.",b:"Cierto: son válidos.",c:"Cierto: son válidos.",d:"Cierto: son válidos."}},
{n:196,q:"De conformidad con lo dispuesto en el Reglamento General de Conductores (RD 818/2009), la validez en España de los permisos de conducción expedidos en terceros países estará condicionada:",o:{a:"A que el permiso de conducción se encuentre en vigor.",b:"A que su titular tenga la edad requerida en España para la obtención de un permiso español equivalente.",c:"A que no haya transcurrido el plazo de seis meses, como máximo, contado desde que su titular adquiera su residencia normal en España, debidamente acreditada.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres condiciones."}},
{n:197,q:"Kent, ciudadano camerunés con permiso de conducción válido y en vigor expedido por aquel país, y con residencia normal en España desde hace ocho meses, conduce habitualmente un turismo. Teniendo en cuenta lo anterior, indique la afirmación correcta:",o:{a:"Kent no puede conducir legalmente en España porque el permiso de conducción camerunés no tiene validez en España.",b:"Kent no puede conducir en España con el permiso camerunés porque lleva residiendo más de seis meses en nuestro país y su permiso ha dejado de tener validez.",c:"Kent puede conducir legalmente en España porque el permiso camerunés es válido y está en vigor, según la legislación de aquel país y los tratados internacionales que regulan esta materia.",d:"Kent puede conducir en España, siempre y cuando obtenga una habilitación especial expedida por la Dirección General de Tráfico e inscriba su permiso en el Registro de Conductores e Infractores."},correct:"b",why:{a:"No es por falta de reconocimiento, sino por exceso del plazo de 6 meses.",b:"Correcto: superado el plazo de 6 meses de residencia normal, el permiso de países no UE/EEE sin convenio pierde validez en España.",c:"No: el plazo de 6 meses ha vencido.",d:"No es ese el procedimiento."}},
{n:198,q:"De conformidad con lo establecido en el Reglamento General de Conductores (RD 818/2009), y con relación al permiso internacional de conducción, indique la respuesta incorrecta:",o:{a:"Autoriza a conducir temporalmente por el territorio de todos los estados contratantes, con excepción del Estado que lo ha expedido.",b:"Tiene una validez de cinco años.",c:"Se ajustará al modelo establecido en el Convenio Internacional de Ginebra de 19 de septiembre de 1949 y tendrá una validez de un año.",d:"Se expide conforme al modelo que se recoge en el Anexo II del Reglamento General de Conductores."},correct:"b",why:{a:"Correcto.",b:"La validez del permiso internacional es de 1 año, no 5.",c:"Correcto.",d:"Correcto."}},
{n:199,q:"Antoine, ciudadano francés, con permiso de conducción francés en vigor y con residencia normal en España, comete una infracción de tráfico que lleva aparejada la pérdida de seis puntos. Teniendo en cuenta lo anterior, indique la respuesta correcta:",o:{a:"El Estado Español no puede proceder a la detracción de puntos de su permiso de conducción porque se trata de un permiso expedido por otro país.",b:"El Estado Español puede proceder a la detracción de puntos solo en el caso de que dicho conductor, de manera voluntaria, haya solicitado la anotación de los datos de su permiso en el Registro de Conductores e Infractores.",c:"El Estado Español dará cuenta al Gobierno de Francia de la infracción cometida para que por parte de este Estado se proceda a la detracción de puntos correspondiente.",d:"El Estado Español puede proceder a la detracción de puntos, pero con anterioridad debe proceder de oficio a canjear el permiso de conducción francés por uno español."},correct:"d",why:{a:"Sí puede, previo canje.",b:"No es voluntario; el canje puede ser de oficio.",c:"No: España lo gestiona directamente mediante el canje.",d:"Correcto: la JPT procede de oficio al canje del permiso francés por uno español para aplicar la normativa de puntos."}},
{n:200,q:"De conformidad con lo previsto en el art.18 del Reglamento General de Conductores (RD 818/2009), respecto al canje de permisos de conducción expedidos en países miembros de la UE o en Estados Parte del Acuerdo sobre el Espacio Económico Europeo, indique la respuesta incorrecta:",o:{a:"El titular de un permiso de conducción vigente expedido en cualquiera de estos Estados, que haya establecido su residencia normal en España, podrá solicitar en cualquier momento de la Jefatura Provincial de Tráfico en la que desee obtenerlo, el canje de su permiso de conducción por otro español equivalente.",b:"La Dirección General de Tráfico tramitará las solicitudes de canje, tras comprobar que el titular reúne los requisitos previstos en el anexo III, apartado F de dicho Reglamento.",c:"La Jefatura Provincial de Tráfico receptora de una solicitud de canje, después de comprobar, en su caso, la autenticidad, validez y vigencia del permiso presentado, concederá o denegará, según proceda, el canje solicitado.",d:"La resolución que otorgue la concesión o denegación, con indicación del Estado que haya expedido el permiso y los datos que figuren en el mismo, se harán constar en el Registro de conductores e infractores."},correct:"b",why:{a:"Correcto.",b:"Las solicitudes de canje son tramitadas por la Jefatura Provincial de Tráfico, no directamente por la DGT.",c:"Correcto.",d:"Correcto."}},
{n:201,q:"Respecto al canje de permisos de conducir expedidos en países miembros de la UE o en Estados Parte del Acuerdo sobre el Espacio Económico Europeo, las Jefaturas Provinciales de Tráfico procederán al canje de oficio:",o:{a:"Cuando, a consecuencia de la aplicación de la normativa española a sus titulares, sea necesario imponer adaptaciones, restricciones u otras limitaciones en personas, vehículos o de circulación durante la conducción.",b:"Cuando su titular haya sido sancionado en firme en vía administrativa por la comisión de infracciones que lleven aparejada la pérdida de puntos, a los efectos de poder aplicarles las disposiciones nacionales relativas a la restricción, la suspensión, la retirada o la pérdida de vigencia del permiso de conducción.",c:"Cuando sea necesario para poder declarar la nulidad o lesividad del permiso de conducción en cuestión.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Las tres son causas de canje de oficio."}},
{n:202,q:"Respecto al canje de oficio de permisos de conducir expedidos en países miembros de la UE o en Estados Parte del Acuerdo sobre el Espacio Económico Europeo, el art.19 del Reglamento General de Conductores (RD 818/2009) establece que:",o:{a:"Para poder efectuar el canje de oficio será necesario que el titular del permiso tenga su residencia normal en España.",b:"La resolución que a tales efectos se dicte por la Jefatura Provincial de Tráfico con indicación del Estado que haya expedido el permiso de conducción y los datos que figuren en el mismo, se harán constar en el Registro de conductores e infractores.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:203,q:"Hamad, ciudadano marroquí, con permiso de conducción en vigor expedido por aquel país, lleva residiendo en España desde hace seis meses. Para que Mohamed pueda seguir conduciendo legalmente en España debe:",o:{a:"Obtener un permiso de conducción internacional en cualquiera de las Jefaturas Provinciales de Tráfico de nuestro país.",b:"Canjear su permiso de conducción por el equivalente español.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{a:"Parcial: también puede canjear si hay convenio.",b:"✓ Respuesta oficial. Parcial: el canje es la vía si existe acuerdo bilateral.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: ambas opciones son válidas.",d:"Las dos son válidas."}},
{n:204,q:"De conformidad con lo previsto en el Reglamento General de Conductores (RD 818/2009), con relación al canje de permisos de conducir expedidos por países de la Unión Europea, indique la respuesta incorrecta:",o:{a:"El titular de un permiso de este tipo puede solicitar en cualquier momento el canje de dicho permiso, por otro español equivalente.",b:"Para poder efectuar el canje de oficio será necesario que el titular del permiso tenga su residencia normal en España o en cualquier otro país miembro de la Unión Europea.",c:"Las Jefaturas provinciales de tráfico procederán al canje de oficio cuando, a consecuencia de la aplicación de la normativa española a sus titulares sea necesario imponer adaptaciones, restricciones y otras limitaciones en personas, vehículos o de circulación durante la conducción.",d:"Las Jefaturas provinciales de tráfico procederán al canje de oficio cuando sea necesario para poder declarar la nulidad o lesividad del permiso de conducción en cuestión."},correct:"b",why:{a:"Correcto.",b:"Para el canje de oficio se requiere residencia normal en España, no en cualquier país de la UE.",c:"Correcto.",d:"Correcto."}},
{n:205,q:"La Ley de Seguridad Vial (RDL 6/2015) regula las autorizaciones administrativas relativas a los vehículos:",o:{a:"En el Capítulo IV de su Título V, artículos 69 a 73.",b:"En el Capítulo III de su Título IV, artículos 66 a 68.",c:"En el Capítulo II de su Título V, artículos 63 a 66.",d:"En el Capítulo I de su Título IV, artículos 61 a 63."},correct:"b",why:{a:"No.",b:"Correcto: las autorizaciones de vehículos (permiso de circulación) están en el Cap.III del Tit.IV, arts.66-68.",c:"No.",d:"No."}},
{n:206,q:"Según el art.66 de la Ley de Seguridad Vial (RDL 6/2015), la circulación de vehículos exigirá que estos obtengan previamente el correspondiente permiso de circulación dirigido a:",o:{a:"Verificar que estén en perfecto estado de funcionamiento.",b:"Que se ajusten en sus características, equipos, repuestos y accesorios a las prescripciones técnicas que se fijen reglamentariamente.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambos fines.",d:"Las dos son ciertas."}},
{n:207,q:"Según el art.66 de la Ley de Seguridad Vial (RDL 6/2015), en el caso de vehículos dotados de sistema de conducción automatizada, sus características, tanto de grado de automatización como del entorno operacional de uso, se consignarán en el permiso de circulación:",o:{a:"Conforme se desarrolle reglamentariamente.",b:"Conforme a lo establecido en el Anexo II de dicha Ley de Seguridad Vial.",c:"Conforme a lo previsto en el Anexo III de dicha Ley de Seguridad Vial.",d:"Todas las respuestas anteriores son incorrectas."},correct:"a",why:{a:"Correcto: art.66 LSV → conforme se desarrolle reglamentariamente.",b:"No.",c:"No.",d:"La a es correcta."}},
{n:208,q:"Según lo establecido en el art.66 de la Ley de Seguridad Vial (RDL 6/2015), respecto al permiso de circulación de vehículos, indique la afirmación incorrecta:",o:{a:"Se prohíbe la circulación de vehículos que no estén dotados del citado permiso.",b:"El permiso de circulación quedará extinguido cuando no se cumplan los requisitos establecidos en el Anexo III de dicha Ley de Seguridad Vial.",c:"El permiso de circulación debe renovarse cuando varíe la titularidad registral del vehículo.",d:"El permiso de circulación quedará extinguido cuando éste se dé de baja en el correspondiente registro, a instancia de parte o por comprobarse que no es apto para la circulación, en los términos que reglamentariamente se determine."},correct:"b",why:{a:"Correcto.",b:"La extinción del permiso de circulación no se vincula al Anexo III sino a causas reglamentarias.",c:"Correcto.",d:"Correcto."}},
{n:209,q:"La circulación de un vehículo sin el permiso de circulación, bien por no haberlo obtenido o porque haya sido objeto de declaración de pérdida de vigencia, de nulidad o anulada, da lugar:",o:{a:"A la inmovilización del mismo hasta que se disponga de dicho permiso, en los términos que reglamentariamente se determine.",b:"A la comisión de una infracción de carácter grave del art.77 k).",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"✓ Respuesta oficial. Cierto: inmovilización.",b:"Cierto: infracción grave.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: ambas.",d:"Las dos son ciertas."}},
{n:210,q:"Los vehículos a motor, los ciclomotores y los remolques de masa MMA superior a la que reglamentariamente se determine, tendrán documentadas sus características técnicas esenciales en la tarjeta de inspección técnica, en la que se harán constar, en los términos que reglamentariamente se determine:",o:{a:"Las reformas que se autoricen.",b:"La verificación de su estado de servicio y mantenimiento.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:211,q:"Según el art.68 de la Ley de Seguridad Vial (RDL 6/2015) y con respecto a la matriculación de vehículos, indique la afirmación incorrecta:",o:{a:"Para poner en circulación vehículos a motor, así como remolques de MMA superior a la que reglamentariamente se determine, es preciso matricularlos y que lleven las placas de matrícula con los caracteres que se les asigne del modo que se establezca, siendo exigible también a los ciclomotores, en los términos que reglamentariamente se determine.",b:"La matriculación ordinaria será única para cada vehículo, salvo en los supuestos que se determinen reglamentariamente.",c:"En casos excepcionales, la autoridad competente para expedir el permiso de circulación podrá conceder permisos extraordinarios, conforme a lo dispuesto en el Anexo II de dicha Ley.",d:"Cuando concurran circunstancias que puedan afectar a la Seguridad Nacional, el Secretario de Estado de Seguridad podrá autorizar una nueva matrícula distinta de la inicialmente asignada."},correct:"c",why:{a:"Correcto.",b:"Correcto.",c:"✓ Respuesta oficial. Correcto.",d:"⚠ Mi respuesta inicial (incorrecta): El que autoriza la matrícula de seguridad nacional es el Ministro del Interior, no el Secretario de Estado de Seguridad."}},
{n:212,q:"Según el art.68 de la Ley de Seguridad Vial (RDL 6/2015):",o:{a:"En casos justificados, la autoridad competente para expedir el permiso de circulación podrá conceder permisos de circulación temporales y provisionales.",b:"Cuando concurran circunstancias que puedan afectar a la Seguridad Nacional, Ministro del Interior podrá autorizar una matrícula extraordinaria que sustituya a la inicialmente asignada.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"✓ Respuesta oficial. Cierto.",b:"Cierto.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: ambas.",d:"Las dos son ciertas."}},
{n:213,q:"El tipo de matriculas que puedan autorizarse, en circunstancias que puedan afectar a la Seguridad Nacional, no serán públicas en el Registro General de Vehículos e, incluso en circunstancias excepcionales, podrá utilizarse una titularidad supuesta en el marco de la actuación:",o:{a:"De las Fuerzas y Cuerpos de Seguridad.",b:"Del Centro Nacional de Inteligencia en el tráfico jurídico.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:214,q:"De conformidad con lo establecido en el Reglamento General de Conductores (RD 818/2009), las autorizaciones administrativas pueden ser objeto de declaración de nulidad o lesividad...",o:{a:"En los casos previstos en los artículos 67 y 68 del RDL 6/2015 por el que se aprueba el Texto Refundido de la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.",b:"En los supuestos previstos en el Anexo V de este Reglamento.",c:"Cuando concurra alguno de los supuestos previstos en la Ley 39/2015, del Procedimiento Administrativo Común de las Administraciones Públicas.",d:"Todas las respuestas anteriores son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"La Ley 39/2015 del PAC es la norma general aplicable para la nulidad y lesividad.",d:"La c es correcta."}},
{n:215,q:"Según el art.70 de la Ley de Seguridad Vial (RDL 6/2015), y con respecto a la pérdida de vigencia de las autorizaciones administrativas, por desaparición de los requisitos para su otorgamiento, indique la afirmación incorrecta",o:{a:"La vigencia de las autorizaciones administrativas estará subordinada a que se mantengan los requisitos exigidos para su otorgamiento.",b:"El titular de una autorización cuya pérdida de vigencia le haya sido notificada, podrá obtenerla de nuevo siguiendo el procedimiento establecido reglamentariamente.",c:"El organismo autónomo Jefatura Central de Tráfico podrá declarar la pérdida de vigencia de las autorizaciones reguladas en el título IV cuando se acredite la desaparición de los requisitos sobre conocimientos, habilidades o aptitudes psicofísicas exigidas para su autorización.",d:"Para acordar la pérdida de vigencia, la Administración deberá notificar la presunta carencia del requisito exigido al interesado, a quien se concederá la facultad de acreditar su existencia en los términos que reglamentariamente se determine."},correct:"b",why:{a:"Correcto.",b:"✓ Respuesta oficial. Correcto.",c:"⚠ Mi respuesta inicial (incorrecta): La JCT puede declarar la pérdida de vigencia de las autorizaciones de conducción, no de todas las del Título IV (que incluye también permisos de circulación de vehículos).",d:"Correcto."}},
{n:216,q:"De conformidad con lo establecido en el Reglamento General de Conductores (RD 818/2009), y con relación a la declaración de pérdida de vigencia de las autorizaciones administrativas para conducir, indique la afirmación incorrecta:",o:{a:"Se declarará la pérdida de vigencia de las autorizaciones cuyo titular no posea los requisitos para su otorgamiento.",b:"Se declarará la pérdida de vigencia de las autorizaciones cuyo titular haya perdido totalmente su asignación de puntos.",c:"La competencia para declarar la pérdida de vigencia corresponde al Jefe Provincial de Tráfico.",d:"La resolución que declare la pérdida de vigencia deberá ser notificada al interesado en el plazo máximo de 15 días."},correct:"d",why:{a:"Correcto.",b:"Correcto.",c:"Correcto.",d:"El plazo de notificación legal no es de 15 días."}},
{n:217,q:"De conformidad con lo establecido en el Real Decreto 818/2009 por el que se aprueba el Reglamento General de Conductores y con relación a la pérdida de vigencia de las autorizaciones administrativas para conducir, indique la afirmación incorrecta:",o:{a:"Se declarará dicha pérdida de vigencia cuando el titular de la autorización haya perdido totalmente su asignación de puntos.",b:"Se declarará dicha pérdida de vigencia cuando el titular de la autorización no posea los requisitos exigidos para su otorgamiento.",c:"La competencia para la declaración de la pérdida de vigencia corresponde al Director General de Tráfico, que podrá delegarla en el Jefe Provincial.",d:"La resolución que declare la pérdida de vigencia debe ser notificada en el plazo máximo de seis meses."},correct:"c",why:{a:"Correcto.",b:"Correcto.",c:"La competencia corresponde al Jefe Provincial de Tráfico directamente, no al Director General.",d:"Correcto."}},
{n:218,q:"De conformidad con lo establecido en el Real Decreto 818/2009 por el que se aprueba el Reglamento General de Conductores y con relación a la pérdida de vigencia de la autorización administrativa para conducir por haber perdido la totalidad de los puntos asignados, indique la respuesta incorrecta:",o:{a:"El titular de la autorización puede obtener un nuevo permiso o licencia de la misma clase realizando y superando con aprovechamiento un curso de sensibilización y reeducación vial.",b:"La Resolución de la pérdida total de puntos asignados deberá notificarse al titular de la licencia en el plazo máximo de un mes.",c:"No se podrá obtener un nuevo permiso o licencia hasta que hayan transcurrido seis meses desde la fecha de notificación del acuerdo de pérdida de vigencia, salvo que se trate de conductores profesionales, en cuyo caso el plazo será de tres meses.",d:"Si en los tres años siguientes a la obtención de una nueva autorización se acordara su pérdida de vigencia por haber perdido otra vez la totalidad del crédito de puntos asignados, no se podrá obtener un nuevo permiso o licencia hasta transcurridos doce meses desde la notificación del acuerdo de pérdida de vigencia, salvo que se trate de conductores profesionales, en cuyo caso el plazo será de seis meses."},correct:"b",why:{a:"⚠ Mi respuesta inicial (incorrecta): Para obtener un nuevo permiso se requiere además superar la prueba de control de conocimientos; solo indicar el curso es incompleto.",b:"✓ Respuesta oficial. Correcto.",c:"Correcto.",d:"Correcto."}}];
